import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function sha256Hex(text: string): Promise<string> {
  const encoded = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', encoded);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const { resource_type, resource_id, otp_code } = await req.json();

    if (!resource_type || !resource_id || !otp_code) {
      return new Response(
        JSON.stringify({ error: 'resource_type, resource_id and otp_code are required' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    if (!/^\d{6}$/.test(otp_code)) {
      return new Response(
        JSON.stringify({ error: 'OTP must be exactly 6 digits' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // Fetch the latest unverified, unexpired OTP for this resource
    const now = new Date().toISOString();
    const { data: otpRows, error: fetchError } = await supabaseAdmin
      .from('otp_verifications')
      .select('id, otp_hash, expires_at, attempts, verified_at')
      .eq('resource_type', resource_type)
      .eq('resource_id', resource_id)
      .is('verified_at', null)
      .gte('expires_at', now)
      .order('created_at', { ascending: false })
      .limit(1);

    if (fetchError) throw new Error(fetchError.message);
    if (!otpRows?.length) {
      return new Response(
        JSON.stringify({ verified: false, error: 'No valid OTP found. It may have expired — request a new one.' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const record = otpRows[0];

    // Enforce max 3 attempts
    if (record.attempts >= 3) {
      return new Response(
        JSON.stringify({ verified: false, error: 'Too many failed attempts. Request a new OTP.' }),
        { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const submittedHash = await sha256Hex(otp_code.trim());
    const matched = submittedHash === record.otp_hash;

    if (!matched) {
      // Increment attempts
      await supabaseAdmin
        .from('otp_verifications')
        .update({ attempts: record.attempts + 1 })
        .eq('id', record.id);

      const remaining = 3 - (record.attempts + 1);
      return new Response(
        JSON.stringify({
          verified: false,
          error: `Incorrect OTP. ${remaining} attempt${remaining !== 1 ? 's' : ''} remaining.`,
          attempts_remaining: remaining,
        }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    // Mark as verified
    await supabaseAdmin
      .from('otp_verifications')
      .update({ verified_at: now })
      .eq('id', record.id);

    return new Response(
      JSON.stringify({ verified: true }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('verify-otp error:', msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function sha256Hex(text: string): Promise<string> {
  const encoded = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', encoded);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function generateOTP(): string {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return String(array[0] % 1000000).padStart(6, '0');
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const { resource_type, resource_id, admin_id, context_label } = await req.json();

    if (!resource_type || !resource_id) {
      return new Response(JSON.stringify({ error: 'resource_type and resource_id are required' }), {
        status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // Rate-limit: max 3 OTP requests per 10 minutes per resource
    const tenMinsAgo = new Date(Date.now() - 10 * 60 * 1000).toISOString();
    const { count } = await supabaseAdmin
      .from('otp_verifications')
      .select('id', { count: 'exact', head: true })
      .eq('resource_id', resource_id)
      .eq('resource_type', resource_type)
      .gte('created_at', tenMinsAgo);

    if ((count ?? 0) >= 3) {
      return new Response(
        JSON.stringify({ error: 'Rate limit: max 3 OTP requests per 10 minutes. Try again later.' }),
        { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const otp = generateOTP();
    const otpHash = await sha256Hex(otp);
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();

    const { error: insertError } = await supabaseAdmin
      .from('otp_verifications')
      .insert({
        admin_id: admin_id ?? null,
        resource_type,
        resource_id,
        otp_hash: otpHash,
        expires_at: expiresAt,
      });

    if (insertError) throw new Error(`DB insert failed: ${insertError.message}`);

    const adminEmail = Deno.env.get('ADMIN_EMAIL') ?? 'info@inyathitours.com';
    const resendKey  = Deno.env.get('RESEND_API_KEY') ?? '';

    if (!resendKey) {
      console.warn('RESEND_API_KEY not set — OTP generated but email not sent. OTP:', otp);
      return new Response(
        JSON.stringify({ success: true, warning: 'Email not configured; OTP logged server-side only.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const label = context_label ?? resource_type.replace(/_/g, ' ');
    const emailRes = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: `Bearer ${resendKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: `INYATHI Fleet <noreply@inyathitours.com>`,
        to: [adminEmail],
        subject: `🔐 INYATHI OTP Code — ${label}`,
        html: `
          <div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px 24px">
            <h2 style="color:#0f2744;margin-bottom:4px">INYATHI Fleet Management</h2>
            <p style="color:#64748b;margin-top:0">One-Time Password</p>
            <hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0">
            <p style="font-size:14px;color:#1e293b">A <strong>${label}</strong> action requires your approval. Use the code below to verify:</p>
            <div style="background:#f0f4f8;border-radius:12px;padding:24px;text-align:center;margin:20px 0">
              <span style="font-size:42px;font-weight:900;letter-spacing:12px;color:#0f2744">${otp}</span>
            </div>
            <p style="font-size:13px;color:#64748b">⏱ This code expires in <strong>15 minutes</strong>.<br>🔒 If you did not request this, contact your system administrator immediately.</p>
            <hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0">
            <p style="font-size:11px;color:#94a3b8">INYATHI (Pty) Ltd · Fleet Management System</p>
          </div>`,
      }),
    });

    if (!emailRes.ok) {
      const errBody = await emailRes.text();
      throw new Error(`Resend API error: ${errBody}`);
    }

    return new Response(JSON.stringify({ success: true }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('send-otp-email error:', msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

'use client';

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight, Calendar } from 'lucide-react';
import { Booking, Vehicle } from '@/lib/storage';

interface CalendarGridProps {
  bookings: Booking[];
  vehicles: Vehicle[];
  onSelectDate: (date: Date) => void;
  onSelectBooking: (booking: Booking) => void;
}

const PALETTE_COLORS = [
  '#3B82F6', // Blue
  '#10B981', // Emerald
  '#EF4444', // Red
  '#F59E0B', // Amber
  '#8B5CF6', // Violet
  '#EC4899', // Pink
  '#F97316', // Orange
  '#14B8A6', // Teal
  '#06B6D4', // Cyan
  '#6366F1', // Indigo
];

export default function CalendarGrid({
  bookings,
  vehicles,
  onSelectDate,
  onSelectBooking
}: CalendarGridProps) {
  const [currentDate, setCurrentDate] = useState<Date>(() => new Date());

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  // Month names
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  // Days in month
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  // First day of month index (0-6)
  const firstDayIndex = new Date(year, month, 1).getDay();

  // Navigate months
  const prevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const jumpToToday = () => {
    setCurrentDate(new Date());
  };

  // Helper to normalize to start of day
  const getMidnight = (d: Date) => {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  };

  // Generate complete grid dates including leading/trailing padding
  const firstDayIndexOffset = firstDayIndex;
  const totalSlots = Math.ceil((firstDayIndexOffset + daysInMonth) / 7) * 7;

  const gridDates: Date[] = [];
  for (let i = 0; i < totalSlots; i++) {
    gridDates.push(new Date(year, month, 1 - firstDayIndexOffset + i));
  }

  // Partition into weeks
  const weeks: Date[][] = [];
  for (let i = 0; i < gridDates.length; i += 7) {
    weeks.push(gridDates.slice(i, i + 7));
  }

  // Find active bookings on a specific date
  const getBookingsOnDate = (date: Date): Booking[] => {
    const checkTime = getMidnight(date);

    return bookings.filter(b => {
      const start = getMidnight(new Date(b.start_date));
      const end = getMidnight(new Date(b.end_date));
      return checkTime >= start && checkTime <= end;
    });
  };

  // Assign deterministic color
  const getBookingColor = (b: Booking) => {
    if (b.is_rented_vehicle) {
      return '#6366F1'; // Indigo for rented vehicles
    }
    const vehicle = vehicles.find(v => v.registration_no === b.assigned_vehicle_reg);
    if (vehicle?.color) {
      return vehicle.color;
    }
    const hash = b.invoice_no.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return PALETTE_COLORS[hash % PALETTE_COLORS.length];
  };

  // Get and allocate tracks for bookings overlapping a week
  const getWeekTracks = (week: Date[]) => {
    const weekStart = getMidnight(week[0]);
    const weekEnd = getMidnight(week[6]);

    // Find all bookings overlapping with this week
    const weekBookings = bookings.filter(b => {
      const start = getMidnight(new Date(b.start_date));
      const end = getMidnight(new Date(b.end_date));
      return start <= weekEnd && end >= weekStart;
    });

    // Sort: earlier start first, longer duration second
    const sortedBookings = [...weekBookings].sort((a, b) => {
      const startA = getMidnight(new Date(a.start_date));
      const startB = getMidnight(new Date(b.start_date));
      if (startA !== startB) return startA - startB;

      const durationA = getMidnight(new Date(a.end_date)) - startA;
      const durationB = getMidnight(new Date(b.end_date)) - startB;
      return durationB - durationA;
    });

    const allocated: { 
      booking: Booking; 
      startCol: number; 
      endCol: number; 
      track: number;
      startsInWeek: boolean;
      endsInWeek: boolean;
    }[] = [];

    sortedBookings.forEach(booking => {
      const bookingStart = getMidnight(new Date(booking.start_date));
      const bookingEnd = getMidnight(new Date(booking.end_date));

      const startsInWeek = bookingStart >= weekStart;
      const endsInWeek = bookingEnd <= weekEnd;

      // Determine starting column index (0-6)
      let startCol = 0;
      if (startsInWeek) {
        for (let i = 0; i < 7; i++) {
          if (getMidnight(week[i]) === bookingStart) {
            startCol = i;
            break;
          }
        }
      }

      // Determine ending column index (0-6)
      let endCol = 6;
      if (endsInWeek) {
        for (let i = 0; i < 7; i++) {
          if (getMidnight(week[i]) === bookingEnd) {
            endCol = i;
            break;
          }
        }
      }

      // Find first available track
      let track = 0;
      while (true) {
        const overlaps = allocated.some(item => 
          item.track === track && 
          !(endCol < item.startCol || startCol > item.endCol)
        );
        if (!overlaps) {
          break;
        }
        track++;
      }

      allocated.push({
        booking,
        startCol,
        endCol,
        track,
        startsInWeek,
        endsInWeek
      });
    });

    return allocated;
  };

  const dayLabels = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];

  return (
    <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
      {/* Calendar Header */}
      <div className="flex items-center justify-between p-5 border-b border-slate-100 bg-slate-50/50">
        <div className="flex items-center gap-2.5">
          <Calendar className="w-5 h-5 text-teal-600" />
          <h2 className="text-base font-extrabold text-slate-850">
            {monthNames[month]} {year}
          </h2>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={jumpToToday}
            className="text-xs font-bold px-3 py-1.5 bg-white border border-slate-200 hover:border-slate-300 rounded-lg shadow-xs transition-all hover:bg-slate-50 text-slate-700"
          >
            Today
          </button>

          <div className="flex items-center border border-slate-200 rounded-lg bg-white shadow-xs overflow-hidden">
            <button
              onClick={prevMonth}
              className="p-1.5 hover:bg-slate-50 border-r border-slate-100 transition-colors text-slate-600"
              title="Previous Month"
            >
              <ChevronLeft className="w-4.5 h-4.5" />
            </button>
            <button
              onClick={nextMonth}
              className="p-1.5 hover:bg-slate-50 transition-colors text-slate-600"
              title="Next Month"
            >
              <ChevronRight className="w-4.5 h-4.5" />
            </button>
          </div>
        </div>
      </div>

      {/* Days of Week Row */}
      <div className="grid grid-cols-7 border-b border-slate-100 text-center bg-slate-50/20">
        {dayLabels.map((day, idx) => (
          <div key={idx} className="py-3 text-[11px] font-extrabold text-slate-400 tracking-widest uppercase">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Weeks & Days Grid */}
      <div className="flex flex-col bg-slate-100/60 gap-[1px]">
        {weeks.map((week, weekIdx) => {
          const weekTracks = getWeekTracks(week);
          const maxTrack = weekTracks.reduce((max, t) => Math.max(max, t.track), -1);
          // Dynamically adjust height of week row based on total stacked tracks
          const rowHeightClass = maxTrack >= 4 ? 'min-h-[145px]' : 'min-h-[115px]';

          return (
            <div key={weekIdx} className={`relative bg-white ${rowHeightClass} transition-all duration-200`}>
              {/* Day cells grid */}
              <div className="grid grid-cols-7 h-full absolute inset-0">
                {week.map((date, dayIdx) => {
                  const isCurrentMonth = date.getMonth() === month;
                  const dayBookings = getBookingsOnDate(date);
                  const isToday = new Date().toDateString() === date.toDateString();

                  return (
                    <div
                      key={dayIdx}
                      onClick={() => onSelectDate(date)}
                      className={`p-2 flex flex-col justify-between hover:bg-slate-50/40 cursor-pointer transition-colors border-r border-slate-100/70 last:border-r-0 ${
                        !isCurrentMonth ? 'bg-slate-50/20' : ''
                      }`}
                    >
                      {/* Day Number and Dot Indicator */}
                      <div className="flex flex-col items-center self-start gap-1">
                        {isCurrentMonth ? (
                          <span
                            className={`text-xs font-extrabold rounded-full w-6 h-6 flex items-center justify-center transition-colors ${
                              isToday
                                ? 'bg-teal-600 text-white shadow-sm font-black'
                                : 'text-slate-700'
                            }`}
                          >
                            {date.getDate()}
                          </span>
                        ) : (
                          // Faded or empty space to perfectly align with the design
                          <span className="w-6 h-6 text-slate-300 font-extrabold text-xs flex items-center justify-center">
                            {date.getDate()}
                          </span>
                        )}

                        {/* Event indicator orange dot, like in the attached image */}
                        {dayBookings.length > 0 && isCurrentMonth && (
                          <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />
                        )}
                      </div>

                      {/* Flex spacer */}
                      <div className="flex-1" />
                    </div>
                  );
                })}
              </div>

              {/* Absolute overlay for booking bars */}
              <div className="absolute top-[34px] left-0 right-0 bottom-2 pointer-events-none z-10">
                {weekTracks.map(({ booking, startCol, endCol, track, startsInWeek, endsInWeek }) => {
                  const barColor = getBookingColor(booking);

                  // Horizontal position math
                  const leftPercent = (startCol / 7) * 100;
                  const widthPercent = ((endCol - startCol + 1) / 7) * 105; // Slightly overlap cell border

                  // Adjust padding and rounding so it looks incredibly clean
                  const paddingLeft = startsInWeek ? 6 : 0;
                  const paddingRight = endsInWeek ? 6 : 0;
                  const roundedClass = `${startsInWeek ? 'rounded-l-full' : ''} ${endsInWeek ? 'rounded-r-full' : ''}`;

                  const leftStyle = `calc(${leftPercent}% + ${paddingLeft}px)`;
                  // Subtract padding from both sides
                  const widthStyle = `calc(${((endCol - startCol + 1) / 7) * 100}% - ${paddingLeft + paddingRight}px)`;
                  const topStyle = `${track * 11}px`; // 6px bar + 5px gap

                  const infoTooltip = `Invoice: ${booking.invoice_no}\nClient: ${booking.client_name}\nRoute: ${booking.route}\nVehicle: ${booking.assigned_vehicle_reg}\nStatus: ${booking.status} (${booking.payment_status})`;

                  return (
                    <div
                      key={booking.invoice_no}
                      onClick={(e) => {
                        e.stopPropagation();
                        onSelectBooking(booking);
                      }}
                      title={infoTooltip}
                      style={{
                        left: leftStyle,
                        width: widthStyle,
                        top: topStyle,
                        backgroundColor: barColor,
                      }}
                      className={`absolute h-1.5 pointer-events-auto transition-all cursor-pointer duration-150 hover:brightness-110 hover:scale-y-125 hover:shadow-xs active:scale-95 ${roundedClass}`}
                    />
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { ShieldCheck, X, RefreshCw, AlertCircle } from 'lucide-react';
import { isSupabaseConfigured, supabase } from '@/lib/storage';

interface OTPModalProps {
  isOpen: boolean;
  onClose: () => void;
  onVerifySuccess: () => void;
  title?: string;
  description?: string;
  resourceType?: string;
  resourceId?: string;
}

export default function OTPModal({
  isOpen,
  onClose,
  onVerifySuccess,
  title = 'Security Authentication',
  description = 'A 6-digit administrative verification code is required to authorize this action.',
  resourceType,
  resourceId
}: OTPModalProps) {
  const [code, setCode] = useState<string[]>(['', '', '', '', '', '']);
  const [error, setError] = useState<string>('');
  const [sending, setSending] = useState<boolean>(false);
  const [sentCodeToast, setSentCodeToast] = useState<boolean>(false);
  const [toastMessage, setToastMessage] = useState<string>('');

  const generateAndSendOTP = async () => {
    setSending(true);
    setError('');

    // Get logged-in user email
    let userEmail = 'info@inyathi.com';
    if (typeof window !== 'undefined') {
      const userStr = localStorage.getItem('inyathi_auth_user');
      if (userStr) {
        try {
          const u = JSON.parse(userStr);
          if (u?.email) userEmail = u.email;
        } catch (_) {}
      }
    }

    const resType = resourceType || 'admin_action';
    const resId = resourceId || `act-${Math.floor(100000 + Math.random() * 900000)}`;

    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error: fnError } = await supabase.functions.invoke('send-otp-email', {
          body: { 
            resource_type: resType,
            resource_id: resId,
            admin_id: 'DRV-ADM001', // Sends to the Main Chief Admin
            context_label: title || 'Admin action authorization'
          }
        });

        if (fnError) {
          throw new Error(fnError.message || 'Function invocation failed');
        }

        setToastMessage('A secure OTP has been generated and sent to the Main Admin (alerts@inyathitours.com). Please request the code from them.');
        setSentCodeToast(true);
      } catch (err: any) {
  console.error('Error invoking send-otp-email:', err);
  setError('Failed to send OTP. Please check your connection and try again.');
      } finally {
        setSending(false);
      }
    } else {
      // Simulate sending OTP
      setTimeout(() => {
        const pin = Math.floor(100000 + Math.random() * 900000).toString();

        setSending(false);
        setToastMessage(`An OTP verification code was sent to the Main Admin email inbox. Main Admin shared this code with you: ${pin}`);
        setSentCodeToast(true);
      }, 800);
    }
  };

  useEffect(() => {
    if (isOpen) {
      // Defer state updates to defuse synchronous cascading render warnings
      setTimeout(() => {
        setCode(['', '', '', '', '', '']);
        setError('');
        setSentCodeToast(false);
        generateAndSendOTP();
      }, 0);
    }
  }, [isOpen]);

  useEffect(() => {
    if (sentCodeToast) {
      const timer = setTimeout(() => {
        setSentCodeToast(false);
      }, 10000);
      return () => clearTimeout(timer);
    }
  }, [sentCodeToast]);

  const handleInputChange = (value: string, index: number) => {
    if (isNaN(Number(value))) return;

    const newCode = [...code];
    newCode[index] = value.substring(value.length - 1); // Keep last char
    setCode(newCode);
    setError('');

    // Focus next element
    if (value !== '' && index < 5) {
      const nextInput = document.getElementById(`otp-input-${index + 1}`);
      nextInput?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === 'Backspace' && code[index] === '' && index > 0) {
      const prevInput = document.getElementById(`otp-input-${index - 1}`);
      prevInput?.focus();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const typedCode = code.join('');

    if (typedCode.length < 6) {
      setError('Please fill in all 6 digits.');
      return;
    }

    setSending(true);
    setError('');

    const resType = resourceType || 'admin_action';
    const resId = resourceId || '';

    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error: verifyError } = await supabase.functions.invoke('verify-otp', {
          body: { 
            resource_type: resType,
            resource_id: resId,
            otp_code: typedCode
          }
        });

        if (verifyError) {
          throw new Error(verifyError.message || 'OTP verification failed');
        }

        const isSuccess = data?.verified || data?.success || data?.valid;
        if (isSuccess) {
          setSending(false);
          onVerifySuccess();
        } else {
          setError('Invalid or expired OTP code. Please request a new one or double check with the Admin.');
          setSending(false);
        }
      } catch (err: any) {
  console.error('Error invoking verify-otp:', err);
  setError('Verification failed. Please try again or request a new code.');
  setSending(false);
      }
    } else {
  setSending(false);
  setError('Supabase is not configured. OTP verification is unavailable.');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
      {/* Simulation/Notification Code Toast */}
      {sentCodeToast && (
        <div className="fixed top-6 right-6 z-50 bg-slate-900 border-l-4 border-teal-500 text-white p-4 rounded-lg shadow-xl max-w-sm animate-slide-in flex flex-col gap-1">
          <p className="text-xs font-bold text-teal-400 flex items-center gap-1">
            <ShieldCheck className="w-4 h-4 animate-pulse" />
            SECURE OTP STATUS
          </p>
          <p className="text-xs text-slate-300">
            {toastMessage}
          </p>

          <span className="text-[10px] text-slate-400 text-right mt-0.5 italic">
            Enter the 6-digit code below to proceed.
          </span>
        </div>
      )}

      <div className="bg-white w-full max-w-md rounded-xl shadow-2xl border border-slate-100 overflow-hidden animate-scale-up">
        {/* Modal Header */}
        <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-teal-50 p-2 rounded-lg text-teal-600">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-900">{title}</h3>
              <p className="text-[10px] text-slate-500 font-medium">Security Gate Active</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 p-1.5 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Modal Body */}
        <form onSubmit={handleSubmit} className="p-6">
          <p className="text-xs text-slate-600 text-center mb-6 leading-relaxed">
            {description}
          </p>

          {/* OTP Code Inputs */}
          <div className="flex justify-center gap-2.5 mb-6">
            {code.map((digit, idx) => (
              <input
                key={idx}
                id={`otp-input-${idx}`}
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={1}
                value={digit}
                onChange={(e) => handleInputChange(e.target.value, idx)}
                onKeyDown={(e) => handleKeyDown(e, idx)}
                disabled={sending}
                className="w-11 h-12 text-center text-lg font-bold border-2 border-slate-200 rounded-lg focus:border-teal-500 focus:ring-2 focus:ring-teal-100 outline-none transition-all disabled:opacity-50 text-slate-800 bg-slate-50 focus:bg-white"
                autoFocus={idx === 0}
              />
            ))}
          </div>

          {/* Error Message */}
          {error && (
            <div className="flex items-center gap-2 text-xs font-semibold text-rose-600 bg-rose-50 p-3 rounded-lg mb-6">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {/* Actions */}
          <div className="flex flex-col gap-2.5">
            <button
              type="submit"
              disabled={sending}
              className="w-full bg-teal-600 hover:bg-teal-700 text-white font-semibold py-2.5 rounded-lg text-xs transition-colors flex items-center justify-center gap-1.5 shadow-md disabled:bg-slate-300"
            >
              {sending ? 'Processing Verification...' : 'Verify & Authorize Action'}
            </button>

            <button
              type="button"
              onClick={generateAndSendOTP}
              disabled={sending}
              className="text-[11px] font-bold text-slate-500 hover:text-teal-600 flex items-center gap-1 justify-center py-2 hover:bg-slate-50 rounded-lg transition-colors"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${sending ? 'animate-spin' : ''}`} />
              Resend verification code
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

