    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
  BEGIN
    INSERT INTO public.profiles (id, driver_id, name, role, email)
      VALUES (
          NEW.id,
              'DRV-' || UPPER(SUBSTRING(NEW.id::text, 1, 6)),
                  COALESCE(NEW.raw_user_meta_data->>'full_name', SPLIT_PART(NEW.email, '@', 1)),
