/* ============================================================
   Derek's Roofing — Main Stylesheet
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;900&family=Inter:wght@300;400;500;600;700&display=swap');

/* ── Reset & Base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:       #1B3A6B;
  --navy-dark:  #112548;
  --blue:       #2E6DA4;
  --blue-light: #4A90C4;
  --gold:       #C9922A;
  --white:      #FFFFFF;
  --off-white:  #F7F8FA;
  --light-gray: #E8ECF0;
  --mid-gray:   #8A96A3;
  --charcoal:   #1A1A2E;
  --shadow-sm:  0 2px 8px rgba(27,58,107,.10);
  --shadow-md:  0 6px 24px rgba(27,58,107,.15);
  --shadow-lg:  0 16px 48px rgba(27,58,107,.20);
  --radius:     8px;
  --radius-lg:  16px;
  --transition: .3s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  font-size: 16px;
  line-height: 1.7;
  color: var(--charcoal);
  background: var(--white);
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Typography ───────────────────────────────────────────── */
.display-font { font-family: 'Playfair Display', serif; }

h1,h2,h3 { font-family: 'Playfair Display', serif; line-height: 1.2; }
h1 { font-size: clamp(2.2rem, 5vw, 3.8rem); font-weight: 900; }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 700; }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); font-weight: 600; }

.section-eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--gold);
  display: block;
  margin-bottom: 12px;
}

.section-title { margin-bottom: 16px; color: var(--navy-dark); }
.section-subtitle { font-size: 1.05rem; color: var(--mid-gray); max-width: 560px; }

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  border-radius: var(--radius);
  font-family: 'Inter', sans-serif;
  font-weight: 600;
  font-size: .95rem;
  letter-spacing: .02em;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
}

.btn-primary {
  background: var(--gold);
  color: var(--white);
  border-color: var(--gold);
}
.btn-primary:hover {
  background: #b07e20;
  border-color: #b07e20;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(201,146,42,.4);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,.6);
}
.btn-outline:hover {
  background: rgba(255,255,255,.12);
  border-color: var(--white);
}

.btn-navy {
  background: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}
.btn-navy:hover {
  background: var(--navy-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* ── Navigation ───────────────────────────────────────────── */
#navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  transition: all var(--transition);
  padding: 20px 0;
}

#navbar.scrolled {
  background: rgba(17,37,72,.97);
  backdrop-filter: blur(12px);
  padding: 12px 0;
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-logo img {
  height: 52px;
  width: auto;
  filter: brightness(0) invert(1);
}

.nav-logo-text {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--white);
  line-height: 1.2;
}
.nav-logo-text span { display: block; font-size: .7rem; font-family: 'Inter', sans-serif; font-weight: 400; letter-spacing: .12em; color: var(--gold); text-transform: uppercase; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 36px;
}

.nav-links a {
  color: rgba(255,255,255,.85);
  font-size: .9rem;
  font-weight: 500;
  transition: color var(--transition);
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0; right: 0;
  height: 2px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-links a:hover { color: var(--white); }
.nav-links a:hover::after { transform: scaleX(1); }

.nav-cta { margin-left: 8px; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}

/* ── Hero ─────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url('../header-background.webp');
  background-size: cover;
  background-position: center top;
  background-attachment: fixed;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(17,37,72,.88) 0%,
    rgba(27,58,107,.75) 50%,
    rgba(17,37,72,.70) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
  padding-top: 100px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(201,146,42,.2);
  border: 1px solid rgba(201,146,42,.4);
  color: var(--gold);
  padding: 6px 16px;
  border-radius: 40px;
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 em { font-style: normal; color: var(--gold); }

.hero-sub {
  font-size: 1.15rem;
  color: rgba(255,255,255,.8);
  margin-bottom: 40px;
  max-width: 540px;
}

.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 40px;
  margin-top: 60px;
  padding-top: 40px;
  border-top: 1px solid rgba(255,255,255,.15);
}

.hero-stat strong {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  font-weight: 900;
  color: var(--gold);
}
.hero-stat span { font-size: .85rem; color: rgba(255,255,255,.65); }

/* Roofline shape divider */
.roofline-divider {
  width: 100%;
  overflow: hidden;
  line-height: 0;
}
.roofline-divider svg { display: block; width: 100%; }

/* ── Trust Bar ────────────────────────────────────────────── */
.trust-bar {
  background: var(--navy-dark);
  padding: 20px 0;
}

.trust-bar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255,255,255,.75);
  font-size: .88rem;
  font-weight: 500;
}
.trust-item svg { color: var(--gold); flex-shrink: 0; }

/* ── Section Base ─────────────────────────────────────────── */
.section { padding: 96px 0; }
.section-alt { background: var(--off-white); }
.section-dark { background: var(--navy-dark); color: var(--white); }

.section-header { margin-bottom: 56px; }
.section-header.centered { text-align: center; }
.section-header.centered .section-subtitle { margin: 0 auto; }

/* ── Services ─────────────────────────────────────────────── */
.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}

.service-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  border: 1px solid var(--light-gray);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.service-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 0;
  background: var(--gold);
  transition: height var(--transition);
}
.service-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.service-card:hover::before { height: 100%; }

.service-icon {
  width: 56px; height: 56px;
  background: linear-gradient(135deg, var(--navy), var(--blue));
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--white);
}

.service-card h3 { margin-bottom: 10px; color: var(--navy-dark); }
.service-card p { color: var(--mid-gray); font-size: .95rem; }

/* ── About ────────────────────────────────────────────────── */
.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 72px;
  align-items: center;
}

.about-images {
  position: relative;
  height: 520px;
}
.about-img-main {
  position: absolute;
  top: 0; left: 0;
  width: 78%;
  height: 85%;
  object-fit: cover;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
}
.about-img-secondary {
  position: absolute;
  bottom: 0; right: 0;
  width: 52%;
  height: 52%;
  object-fit: cover;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 4px solid var(--white);
}

.about-badge {
  position: absolute;
  top: 50%; left: 60%;
  transform: translate(-50%, -50%);
  background: var(--gold);
  color: var(--white);
  border-radius: 12px;
  padding: 16px 20px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(201,146,42,.4);
  z-index: 1;
}
.about-badge strong { display: block; font-size: 1.8rem; font-family: 'Playfair Display', serif; }
.about-badge span { font-size: .75rem; font-weight: 600; letter-spacing: .05em; }

.about-text .section-subtitle { margin-bottom: 28px; }

.about-checks { display: flex; flex-direction: column; gap: 14px; margin-bottom: 32px; }
.check-item { display: flex; align-items: flex-start; gap: 12px; }
.check-item svg { color: var(--gold); margin-top: 3px; flex-shrink: 0; }
.check-item p { font-size: .95rem; }
.check-item strong { color: var(--navy-dark); }

/* ── Gallery Preview ──────────────────────────────────────── */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(2, 240px);
  gap: 16px;
}
.gallery-item {
  overflow: hidden;
  border-radius: var(--radius);
  cursor: pointer;
  position: relative;
}
.gallery-item:nth-child(1) { grid-column: 1 / 3; grid-row: 1 / 2; }
.gallery-item:nth-child(4) { grid-column: 4; grid-row: 1 / 3; }

.gallery-item img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.gallery-item:hover img { transform: scale(1.07); }

.gallery-item .overlay {
  position: absolute;
  inset: 0;
  background: rgba(27,58,107,.5);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition);
  color: var(--white);
}
.gallery-item:hover .overlay { opacity: 1; }

.gallery-footer { text-align: center; margin-top: 40px; }

/* ── Testimonials ─────────────────────────────────────────── */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}

.testimonial-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.testimonial-card:hover {
  background: rgba(255,255,255,.1);
  transform: translateY(-4px);
}

.stars { color: var(--gold); font-size: 1.1rem; letter-spacing: 2px; margin-bottom: 16px; }
.testimonial-card blockquote { font-size: .97rem; color: rgba(255,255,255,.8); line-height: 1.75; margin-bottom: 20px; }
.reviewer { display: flex; align-items: center; gap: 12px; }
.reviewer-avatar {
  width: 44px; height: 44px;
  background: linear-gradient(135deg, var(--gold), #e6a832);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: 1rem;
  color: var(--white);
}
.reviewer-name { font-weight: 600; color: var(--white); font-size: .92rem; }
.reviewer-loc { font-size: .8rem; color: rgba(255,255,255,.5); }

/* ── CTA Banner ───────────────────────────────────────────── */
.cta-banner {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, var(--blue) 100%);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%; left: -10%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(201,146,42,.15) 0%, transparent 70%);
}

.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,.7); margin-bottom: 36px; font-size: 1.05rem; }
.cta-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Contact ──────────────────────────────────────────────── */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 72px;
  align-items: start;
}

.contact-info h3 { color: var(--navy-dark); margin-bottom: 20px; }
.contact-info p { color: var(--mid-gray); margin-bottom: 32px; }

.contact-detail {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 24px;
}
.contact-icon {
  width: 44px; height: 44px;
  background: linear-gradient(135deg, var(--navy), var(--blue));
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  color: var(--white);
  flex-shrink: 0;
}
.contact-detail strong { display: block; font-size: .85rem; color: var(--navy-dark); margin-bottom: 2px; }
.contact-detail a, .contact-detail span { color: var(--mid-gray); font-size: .95rem; }
.contact-detail a:hover { color: var(--navy); }

/* Contact Form */
.contact-form {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--light-gray);
}

.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .85rem;
  font-weight: 600;
  color: var(--navy-dark);
  margin-bottom: 6px;
}
.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--light-gray);
  border-radius: var(--radius);
  font-family: 'Inter', sans-serif;
  font-size: .95rem;
  color: var(--charcoal);
  background: var(--off-white);
  transition: all var(--transition);
  outline: none;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--blue);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(46,109,164,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }

/* ── Footer ───────────────────────────────────────────────── */
.footer {
  background: var(--charcoal);
  color: rgba(255,255,255,.65);
  padding: 64px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1.2fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.footer-brand img { height: 48px; filter: brightness(0) invert(1); margin-bottom: 16px; }
.footer-brand p { font-size: .9rem; line-height: 1.7; max-width: 260px; margin-bottom: 24px; }

.social-links { display: flex; gap: 12px; }
.social-link {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.08);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  transition: all var(--transition);
  font-size: .85rem;
}
.social-link:hover { background: var(--gold); color: var(--white); }

.footer-col h4 {
  font-family: 'Inter', sans-serif;
  font-size: .85rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col li a {
  font-size: .9rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col li a:hover { color: var(--gold); }

.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
  font-size: .88rem;
}
.footer-contact-item svg { color: var(--gold); margin-top: 2px; flex-shrink: 0; }
.footer-contact-item a { color: rgba(255,255,255,.55); transition: color var(--transition); }
.footer-contact-item a:hover { color: var(--gold); }

.footer-bottom {
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: .83rem;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { color: rgba(255,255,255,.4); transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--gold); }

/* ── Floating Buttons ─────────────────────────────────────── */
.floating-buttons {
  position: fixed;
  bottom: 28px;
  right: 24px;
  z-index: 900;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}

.float-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: 50px;
  font-family: 'Inter', sans-serif;
  font-size: .88rem;
  font-weight: 600;
  color: var(--white);
  cursor: pointer;
  box-shadow: 0 4px 20px rgba(0,0,0,.25);
  transition: all var(--transition);
  border: none;
  text-decoration: none;
}
.float-btn:hover { transform: translateX(-4px); box-shadow: 0 8px 28px rgba(0,0,0,.3); }

.float-whatsapp { background: #25D366; }
.float-phone { background: var(--navy); }

.float-btn svg { flex-shrink: 0; }
.float-label { transition: all var(--transition); }

/* ── Lightbox ─────────────────────────────────────────────── */
.lightbox-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.92);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.lightbox-overlay.active { opacity: 1; pointer-events: all; }

.lightbox-content {
  max-width: 90vw;
  max-height: 90vh;
  position: relative;
}
.lightbox-content img { max-width: 90vw; max-height: 85vh; object-fit: contain; border-radius: var(--radius); }

.lightbox-close {
  position: fixed;
  top: 20px; right: 24px;
  width: 44px; height: 44px;
  background: rgba(255,255,255,.15);
  border: none;
  border-radius: 50%;
  color: var(--white);
  font-size: 1.4rem;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition);
}
.lightbox-close:hover { background: rgba(255,255,255,.3); }

/* ── Mobile Menu ──────────────────────────────────────────── */
.mobile-menu {
  position: fixed;
  top: 0; right: -100%;
  width: min(320px, 80vw);
  height: 100vh;
  background: var(--navy-dark);
  z-index: 9998;
  transition: right var(--transition);
  padding: 80px 32px 32px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: -8px 0 40px rgba(0,0,0,.4);
}
.mobile-menu.open { right: 0; }
.mobile-menu a {
  color: rgba(255,255,255,.85);
  font-size: 1.1rem;
  font-weight: 500;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,.08);
  transition: color var(--transition);
}
.mobile-menu a:hover { color: var(--gold); }
.mobile-menu .close-menu {
  position: absolute;
  top: 20px; right: 20px;
  background: none; border: none;
  color: var(--white); font-size: 1.5rem;
  cursor: pointer;
}

.menu-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 9997;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.menu-overlay.active { opacity: 1; pointer-events: all; }

/* ── Page Hero (inner pages) ──────────────────────────────── */
.page-hero {
  background: linear-gradient(135deg, var(--navy-dark), var(--navy));
  padding: 140px 0 80px;
  text-align: center;
  color: var(--white);
}
.page-hero h1 { margin-bottom: 12px; }
.page-hero .breadcrumb {
  color: rgba(255,255,255,.55);
  font-size: .9rem;
}
.page-hero .breadcrumb a { color: var(--gold); }
.page-hero .breadcrumb a:hover { text-decoration: underline; }

/* ── FAQ ──────────────────────────────────────────────────── */
.faq-accordion { max-width: 800px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid var(--light-gray);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 24px 0;
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy-dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.faq-question svg { flex-shrink: 0; transition: transform var(--transition); color: var(--gold); }
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .4s ease; }
.faq-answer p { padding-bottom: 24px; color: var(--mid-gray); font-size: .95rem; }

/* ── Policy Pages ─────────────────────────────────────────── */
.policy-content {
  max-width: 800px;
  margin: 0 auto;
  padding: 64px 0;
}
.policy-content h2 { font-size: 1.5rem; margin: 36px 0 12px; color: var(--navy-dark); }
.policy-content h3 { font-size: 1.15rem; margin: 24px 0 8px; }
.policy-content p, .policy-content li { color: var(--mid-gray); margin-bottom: 12px; font-size: .95rem; }
.policy-content ul { padding-left: 20px; list-style: disc; }

/* ── Success Page ─────────────────────────────────────────── */
.success-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: var(--off-white);
}
.success-card {
  background: var(--white);
  padding: 60px 48px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  max-width: 540px;
}
.success-icon {
  width: 80px; height: 80px;
  background: linear-gradient(135deg, #22c55e, #16a34a);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 24px;
  color: var(--white);
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 1024px) {
  .about-grid { grid-template-columns: 1fr; gap: 48px; }
  .about-images { height: 380px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 36px; }
  .contact-grid { grid-template-columns: 1fr; gap: 48px; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero-stats { gap: 24px; flex-wrap: wrap; }
  .gallery-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .gallery-item:nth-child(1), .gallery-item:nth-child(4) { grid-column: auto; grid-row: auto; }
  .services-grid { grid-template-columns: 1fr; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .trust-bar-inner { justify-content: flex-start; }
  .about-img-secondary { display: none; }
  .about-badge { left: auto; right: 12px; top: auto; bottom: 12px; transform: none; }
}

@media (max-width: 480px) {
  .section { padding: 64px 0; }
  .gallery-grid { grid-template-columns: 1fr; }
  .float-label { display: none; }
  .float-btn { padding: 14px; border-radius: 50%; }
  .hero-actions { flex-direction: column; }
  .cta-actions { flex-direction: column; align-items: center; }
}

/* ── Animations ───────────────────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}

.fade-up { animation: fadeUp .7s ease forwards; }
.fade-up-delay-1 { animation-delay: .15s; opacity: 0; }
.fade-up-delay-2 { animation-delay: .3s;  opacity: 0; }
.fade-up-delay-3 { animation-delay: .45s; opacity: 0; }

[data-reveal] {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity .7s ease, transform .7s ease;
}
[data-reveal].revealed {
  opacity: 1;
  transform: none;
}

display_content.json_block:
{"language": "css", "code": "/* ============================================================
   Derek's Roofing — Main Stylesheet
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;900&family=Inter:wght@300;400;500;600;700&display=swap');

/* ── Reset & Base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:       #1B3A6B;
  --navy-dark:  #112548;
  --blue:       #2E6DA4;
  --blue-light: #4A90C4;
  --gold:       #C9922A;
  --white:      #FFFFFF;
  --off-white:  #F7F8FA;
  --light-gray: #E8ECF0;
  --mid-gray:   #8A96A3;
  --charcoal:   #1A1A2E;
  --shadow-sm:  0 2px 8px rgba(27,58,107,.10);
  --shadow-md:  0 6px 24px rgba(27,58,107,.15);
  --shadow-lg:  0 16px 48px rgba(27,58,107,.20);
  --radius:     8px;
  --radius-lg:  16px;
  --transition: .3s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  font-size: 16px;
  line-height: 1.7;
  color: var(--charcoal);
  background: var(--white);
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Typography ───────────────────────────────────────────── */
.display-font { font-family: 'Playfair Display', serif; }

h1,h2,h3 { font-family: 'Playfair Display', serif; line-height: 1.2; }
h1 { font-size: clamp(2.2rem, 5vw, 3.8rem); font-weight: 900; }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 700; }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); font-weight: 600; }

.section-eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--gold);
  display: block;
  margin-bottom: 12px;
}

.section-title { margin-bottom: 16px; color: var(--navy-dark); }
.section-subtitle { font-size: 1.05rem; color: var(--mid-gray); max-width: 560px; }

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  border-radius: var(--radius);
  font-family: 'Inter', sans-serif;
  font-weight: 600;
  font-size: .95rem;
  letter-spacing: .02em;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
}

.btn-primary {
  background: var(--gold);
  color: var(--white);
  border-color: var(--gold);
}
.btn-primary:hover {
  background: #b07e20;
  border-color: #b07e20;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(201,146,42,.4);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,.6);
}
.btn-outline:hover {
  background: rgba(255,255,255,.12);
  border-color: var(--white);
}

.btn-navy {
  background: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}
.btn-navy:hover {
  background: var(--navy-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* ── Navigation ───────────────────────────────────────────── */
#navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  transition: all var(--transition);
  padding: 20px 0;
}

#navbar.scrolled {
  background: rgba(17,37,72,.97);
  backdrop-filter: blur(12px);
  padding: 12px 0;
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-logo img {
  height: 52px;
  width: auto;
  filter: brightness(0) invert(1);
}

.nav-logo-text {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--white);
  line-height: 1.2;
}
.nav-logo-text span { display: block; font-size: .7rem; font-family: 'Inter', sans-serif; font-weight: 400; letter-spacing: .12em; color: var(--gold); text-transform: uppercase; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 36px;
}

.nav-links a {
  color: rgba(255,255,255,.85);
  font-size: .9rem;
  font-weight: 500;
  transition: color var(--transition);
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0; right: 0;
  height: 2px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-links a:hover { color: var(--white); }
.nav-links a:hover::after { transform: scaleX(1); }

.nav-cta { margin-left: 8px; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}

/* ── Hero ─────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url('../header-background.webp');
  background-size: cover;
  background-position: center top;
  background-attachment: fixed;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(17,37,72,.88) 0%,
    rgba(27,58,107,.75) 50%,
    rgba(17,37,72,.70) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
  padding-top: 100px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(201,146,42,.2);
  border: 1px solid rgba(201,146,42,.4);
  color: var(--gold);
  padding: 6px 16px;
  border-radius: 40px;
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 em { font-style: normal; color: var(--gold); }

.hero-sub {
  font-size: 1.15rem;
  color: rgba(255,255,255,.8);
  margin-bottom: 40px;
  max-width: 540px;
}

.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 40px;
  margin-top: 60px;
  padding-top: 40px;
  border-top: 1px solid rgba(255,255,255,.15);
}

.hero-stat strong {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  font-weight: 900;
  color: var(--gold);
}
.hero-stat span { font-size: .85rem; color: rgba(255,255,255,.65); }

/* Roofline shape divider */
.roofline-divider {
  width: 100%;
  overflow: hidden;
  line-height: 0;
}
.roofline-divider svg { display: block; width: 100%; }

/* ── Trust Bar ────────────────────────────────────────────── */
.trust-bar {
  background: var(--navy-dark);
  padding: 20px 0;
}

.trust-bar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255,255,255,.75);
  font-size: .88rem;
  font-weight: 500;
}
.trust-item svg { color: var(--gold); flex-shrink: 0; }

/* ── Section Base ─────────────────────────────────────────── */
.section { padding: 96px 0; }
.section-alt { background: var(--off-white); }
.section-dark { background: var(--navy-dark); color: var(--white); }

.section-header { margin-bottom: 56px; }
.section-header.centered { text-align: center; }
.section-header.centered .section-subtitle { margin: 0 auto; }

/* ── Services ─────────────────────────────────────────────── */
.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}

.service-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  border: 1px solid var(--light-gray);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.service-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 0;
  background: var(--gold);
  transition: height var(--transition);
}
.service-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.service-card:hover::before { height: 100%; }

.service-icon {
  width: 56px; height: 56px;
  background: linear-gradient(135deg, var(--navy), var(--blue));
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--white);
}

.service-card h3 { margin-bottom: 10px; color: var(--navy-dark); }
.service-card p { color: var(--mid-gray); font-size: .95rem; }

/* ── About ────────────────────────────────────────────────── */
.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 72px;
  align-items: center;
}

.about-images {
  position: relative;
  height: 520px;
}
.about-img-main {
  position: absolute;
  top: 0; left: 0;
  width: 78%;
  height: 85%;
  object-fit: cover;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
}
.about-img-secondary {
  position: absolute;
  bottom: 0; right: 0;
  width: 52%;
  height: 52%;
  object-fit: cover;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 4px solid var(--white);
}

.about-badge {
  position: absolute;
  top: 50%; left: 60%;
  transform: translate(-50%, -50%);
  background: var(--gold);
  color: var(--white);
  border-radius: 12px;
  padding: 16px 20px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(201,146,42,.4);
  z-index: 1;
}
.about-badge strong { display: block; font-size: 1.8rem; font-family: 'Playfair Display', serif; }
.about-badge span { font-size: .75rem; font-weight: 600; letter-spacing: .05em; }

.about-text .section-subtitle { margin-bottom: 28px; }

.about-checks { display: flex; flex-direction: column; gap: 14px; margin-bottom: 32px; }
.check-item { display: flex; align-items: flex-start; gap: 12px; }
.check-item svg { color: var(--gold); margin-top: 3px; flex-shrink: 0; }
.check-item p { font-size: .95rem; }
.check-item strong { color: var(--navy-dark); }

/* ── Gallery Preview ──────────────────────────────────────── */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(2, 240px);
  gap: 16px;
}
.gallery-item {
  overflow: hidden;
  border-radius: var(--radius);
  cursor: pointer;
  position: relative;
}
.gallery-item:nth-child(1) { grid-column: 1 / 3; grid-row: 1 / 2; }
.gallery-item:nth-child(4) { grid-column: 4; grid-row: 1 / 3; }

.gallery-item img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.gallery-item:hover img { transform: scale(1.07); }

.gallery-item .overlay {
  position: absolute;
  inset: 0;
  background: rgba(27,58,107,.5);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition);
  color: var(--white);
}
.gallery-item:hover .overlay { opacity: 1; }

.gallery-footer { text-align: center; margin-top: 40px; }

/* ── Testimonials ─────────────────────────────────────────── */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}

.testimonial-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.testimonial-card:hover {
  background: rgba(255,255,255,.1);
  transform: translateY(-4px);
}

.stars { color: var(--gold); font-size: 1.1rem; letter-spacing: 2px; margin-bottom: 16px; }
.testimonial-card blockquote { font-size: .97rem; color: rgba(255,255,255,.8); line-height: 1.75; margin-bottom: 20px; }
.reviewer { display: flex; align-items: center; gap: 12px; }
.reviewer-avatar {
  width: 44px; height: 44px;
  background: linear-gradient(135deg, var(--gold), #e6a832);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: 1rem;
  color: var(--white);
}
.reviewer-name { font-weight: 600; color: var(--white); font-size: .92rem; }
.reviewer-loc { font-size: .8rem; color: rgba(255,255,255,.5); }

/* ── CTA Banner ───────────────────────────────────────────── */
.cta-banner {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, var(--blue) 100%);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%; left: -10%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(201,146,42,.15) 0%, transparent 70%);
}

.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,.7); margin-bottom: 36px; font-size: 1.05rem; }
.cta-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Contact ──────────────────────────────────────────────── */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 72px;
  align-items: start;
}

.contact-info h3 { color: var(--navy-dark); margin-bottom: 20px; }
.contact-info p { color: var(--mid-gray); margin-bottom: 32px; }

.contact-detail {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 24px;
}
.contact-icon {
  width: 44px; height: 44px;
  background: linear-gradient(135deg, var(--navy), var(--blue));
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  color: var(--white);
  flex-shrink: 0;
}
.contact-detail strong { display: block; font-size: .85rem; color: var(--navy-dark); margin-bottom: 2px; }
.contact-detail a, .contact-detail span { color: var(--mid-gray); font-size: .95rem; }
.contact-detail a:hover { color: var(--navy); }

/* Contact Form */
.contact-form {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--light-gray);
}

.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: .85rem;
  font-weight: 600;
  color: var(--navy-dark);
  margin-bottom: 6px;
}
.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--light-gray);
  border-radius: var(--radius);
  font-family: 'Inter', sans-serif;
  font-size: .95rem;
  color: var(--charcoal);
  background: var(--off-white);
  transition: all var(--transition);
  outline: none;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--blue);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(46,109,164,.12);
}
.form-group textarea { resize: vertical; min-height: 120px; }

/* ── Footer ───────────────────────────────────────────────── */
.footer {
  background: var(--charcoal);
  color: rgba(255,255,255,.65);
  padding: 64px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1.2fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.footer-brand img { height: 48px; filter: brightness(0) invert(1); margin-bottom: 16px; }
.footer-brand p { font-size: .9rem; line-height: 1.7; max-width: 260px; margin-bottom: 24px; }

.social-links { display: flex; gap: 12px; }
.social-link {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.08);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  transition: all var(--transition);
  font-size: .85rem;
}
.social-link:hover { background: var(--gold); color: var(--white); }

.footer-col h4 {
  font-family: 'Inter', sans-serif;
  font-size: .85rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col li a {
  font-size: .9rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col li a:hover { color: var(--gold); }

.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
  font-size: .88rem;
}
.footer-contact-item svg { color: var(--gold); margin-top: 2px; flex-shrink: 0; }
.footer-contact-item a { color: rgba(255,255,255,.55); transition: color var(--transition); }
.footer-contact-item a:hover { color: var(--gold); }

.footer-bottom {
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: .83rem;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { color: rgba(255,255,255,.4); transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--gold); }

/* ── Floating Buttons ─────────────────────────────────────── */
.floating-buttons {
  position: fixed;
  bottom: 28px;
  right: 24px;
  z-index: 900;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}

.float-btn {
  display: flex;
  align-items: center;
  gap: 10px;
