/* ============================================================
   Derek's Roofing — Main JavaScript
   ============================================================ */

document.addEventListener('DOMContentLoaded', () => {

  /* ── Navbar scroll effect ─────────────────────────────── */
  const navbar = document.getElementById('navbar');
  const scrollHandler = () => {
    navbar?.classList.toggle('scrolled', window.scrollY > 60);
  };
  window.addEventListener('scroll', scrollHandler, { passive: true });
  scrollHandler();

  /* ── Mobile menu ──────────────────────────────────────── */
  const hamburger   = document.querySelector('.hamburger');
  const mobileMenu  = document.querySelector('.mobile-menu');
  const menuOverlay = document.querySelector('.menu-overlay');
  const closeMenu   = document.querySelector('.close-menu');

  function openMobileMenu() {
    mobileMenu?.classList.add('open');
    menuOverlay?.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
  function closeMobileMenuFn() {
    mobileMenu?.classList.remove('open');
    menuOverlay?.classList.remove('active');
    document.body.style.overflow = '';
  }

  hamburger?.addEventListener('click', openMobileMenu);
  closeMenu?.addEventListener('click', closeMobileMenuFn);
  menuOverlay?.addEventListener('click', closeMobileMenuFn);
  mobileMenu?.querySelectorAll('a').forEach(a => a.addEventListener('click', closeMobileMenuFn));

  /* ── Scroll reveal ────────────────────────────────────── */
  const reveals = document.querySelectorAll('[data-reveal]');
  if (reveals.length) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          const delay = e.target.dataset.revealDelay || 0;
          setTimeout(() => e.target.classList.add('revealed'), delay);
        }
      });
    }, { threshold: 0.12 });
    reveals.forEach(el => observer.observe(el));
  }

  /* ── Lightbox ─────────────────────────────────────────── */
  const overlay  = document.getElementById('lightboxOverlay');
  const lightImg = document.getElementById('lightboxImg');
  const lightClose = document.getElementById('lightboxClose');

  function openLightbox(src, alt) {
    if (!overlay || !lightImg) return;
    lightImg.src = src;
    lightImg.alt = alt || '';
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
  function closeLightbox() {
    overlay?.classList.remove('active');
    document.body.style.overflow = '';
  }

  document.querySelectorAll('[data-lightbox]').forEach(item => {
    item.addEventListener('click', () => {
      const img = item.querySelector('img');
      openLightbox(img.src, img.alt);
    });
  });

  lightClose?.addEventListener('click', closeLightbox);
  overlay?.addEventListener('click', e => { if (e.target === overlay) closeLightbox(); });

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') { closeLightbox(); closeMobileMenuFn(); }
  });

  /* ── FAQ Accordion ────────────────────────────────────── */
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item   = btn.closest('.faq-item');
      const answer = item.querySelector('.faq-answer');
      const isOpen = item.classList.contains('open');

      document.querySelectorAll('.faq-item.open').forEach(openItem => {
        openItem.classList.remove('open');
        openItem.querySelector('.faq-answer').style.maxHeight = null;
      });

      if (!isOpen) {
        item.classList.add('open');
        answer.style.maxHeight = answer.scrollHeight + 'px';
      }
    });
  });

  /* ── Smooth active link ───────────────────────────────── */
  const sections = document.querySelectorAll('section[id]');
  const navLinksAll = document.querySelectorAll('.nav-links a');

  window.addEventListener('scroll', () => {
    let current = '';
    sections.forEach(s => {
      if (window.scrollY >= s.offsetTop - 120) current = s.id;
    });
    navLinksAll.forEach(a => {
      a.classList.toggle('active', a.getAttribute('href') === '#' + current);
    });
  }, { passive: true });

  /* ── Contact form ─────────────────────────────────────── */
  const contactForm = document.getElementById('contactForm');
  if (contactForm) {
    contactForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const btn = contactForm.querySelector('button[type="submit"]');
      const originalText = btn.textContent;
      btn.textContent = 'Sending…';
      btn.disabled = true;

      try {
        const resp = await fetch(contactForm.action, {
          method: 'POST',
          body: new FormData(contactForm)
        });
        if (resp.ok || resp.redirected) {
          window.location.href = 'thankyou.html';
        } else {
          throw new Error();
        }
      } catch {
        // fallback: redirect to PHP handler
        contactForm.submit();
      } finally {
        btn.textContent = originalText;
        btn.disabled = false;
      }
    });
  }

  /* ── Counter animation ────────────────────────────────── */
  function animateCounter(el, target, duration = 1800) {
    const start = performance.now();
    const update = (now) => {
      const progress = Math.min((now - start) / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.round(ease * target) + (el.dataset.suffix || '');
      if (progress < 1) requestAnimationFrame(update);
    };
    requestAnimationFrame(update);
  }

  const counters = document.querySelectorAll('[data-counter]');
  if (counters.length) {
    const counterObs = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          animateCounter(e.target, parseInt(e.target.dataset.counter));
          counterObs.unobserve(e.target);
        }
      });
    }, { threshold: 0.5 });
    counters.forEach(el => counterObs.observe(el));
  }

});

