  <script>
    const dropZone  = document.getElementById('dropZone');
    const fileInput = document.getElementById('fileInput');
    const preview   = document.getElementById('uploadPreview');
    const uploadBtn = document.getElementById('uploadBtn');
    const progressWrap = document.getElementById('progressWrap');
    const progressBar  = document.getElementById('progressBar');
    const status       = document.getElementById('uploadStatus');

    let selectedFiles = new DataTransfer();

    function showToast(msg, type = '') {
      const t = document.getElementById('toast');
      t.textContent = msg;
      t.className = 'toast ' + type + ' show';
      setTimeout(() => t.className = 'toast ' + type, 3500);
    }

    function renderPreviews() {
      preview.innerHTML = '';
      Array.from(selectedFiles.files).forEach((file, i) => {
        const thumb = document.createElement('div');
        thumb.className = 'preview-thumb';
        const img = document.createElement('img');
        img.src = URL.createObjectURL(file);
        img.alt = file.name;
        const btn = document.createElement('button');
        btn.className = 'remove-preview';
        btn.textContent = '×';
        btn.onclick = () => {
          const dt = new DataTransfer();
          Array.from(selectedFiles.files).forEach((f, j) => { if (j !== i) dt.items.add(f); });
          selectedFiles = dt;
          renderPreviews();
        };
        thumb.appendChild(img);
        thumb.appendChild(btn);
        preview.appendChild(thumb);
      });
      uploadBtn.disabled = selectedFiles.files.length === 0;
    }

    function addFiles(files) {
      Array.from(files).forEach(f => selectedFiles.items.add(f));
      renderPreviews();
    }

    dropZone.addEventListener('click', () => fileInput.click());
    dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('drag-over'); });
    dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
    dropZone.addEventListener('drop', e => {
      e.preventDefault();
      dropZone.classList.remove('drag-over');
      addFiles(e.dataTransfer.files);
    });
    fileInput.addEventListener('change', () => { addFiles(fileInput.files); fileInput.value = ''; });

    uploadBtn.addEventListener('click', async () => {
      if (selectedFiles.files.length === 0) return;
      const fd = new FormData();
      Array.from(selectedFiles.files).forEach(f => fd.append('images[]', f));

      uploadBtn.disabled = true;
      progressWrap.style.display = 'block';
      progressBar.style.width = '30%';
      status.textContent = 'Uploading…';

      try {
        const resp = await fetch('upload.php', { method: 'POST', body: fd });
        progressBar.style.width = '100%';
        const data = await resp.json();

        if (data.success) {
          showToast('Images uploaded successfully!', 'success');
          setTimeout(() => location.reload(), 1000);
        } else {
          const failed = (data.results || []).filter(r => !r.success).map(r => r.file + ': ' + r.message).join('\n');
          showToast('Some uploads failed. Check console.', 'error');
          console.error(failed);
        }
      } catch (err) {
        showToast('Upload failed. Please try again.', 'error');
        console.error(err);
      } finally {
        uploadBtn.disabled = false;
        progressWrap.style.display = 'none';
        progressBar.style.width = '0';
        status.textContent = '';
      }
    });

    async function deleteImage(filename) {
      if (!confirm('Delete this image? This cannot be undone.')) return;
      const fd = new FormData();
      fd.append('action', 'delete');
      fd.append('filename', filename);

      try {
        const resp = await fetch('upload.php', { method: 'POST', body: fd });
        const data = await resp.json();
        if (data.success) {
          const card = document.getElementById('card-' + filename);
          card?.remove();
          showToast('Image deleted', 'success');
        } else {
          showToast('Could not delete image', 'error');
        }
      } catch {
        showToast('Error deleting image', 'error');
      }
    }
  </script>
</body>
