    // Gallery lightbox with prev/next
    const items = Array.from(document.querySelectorAll('[data-lightbox]'));
    const lbImg  = document.getElementById('lightboxImg');
    const lbOv   = document.getElementById('lightboxOverlay');
    const lbCt   = document.getElementById('lbCounter');
    let current  = 0;

    function openAt(idx) {
      current = idx;
      lbImg.src = items[idx].dataset.src;
      lbOv.classList.add('active');
      lbCt.textContent = (idx + 1) + ' / ' + items.length;
      document.body.style.overflow = 'hidden';
    }

    items.forEach((el, i) => el.addEventListener('click', () => openAt(i)));

    document.getElementById('lbPrev').addEventListener('click', () => openAt((current - 1 + items.length) % items.length));
    document.getElementById('lbNext').addEventListener('click', () => openAt((current + 1) % items.length));

    document.getElementById('lightboxClose').addEventListener('click', () => {
      lbOv.classList.remove('active');
      document.body.style.overflow = '';
    });
    lbOv.addEventListener('click', e => {
      if (e.target === lbOv) { lbOv.classList.remove('active'); document.body.style.overflow = ''; }
    });
    document.addEventListener('keydown', e => {
      if (!lbOv.classList.contains('active')) return;
      if (e.key === 'ArrowLeft') openAt((current - 1 + items.length) % items.length);
      if (e.key === 'ArrowRight') openAt((current + 1) % items.length);
      if (e.key === 'Escape') { lbOv.classList.remove('active'); document.body.style.overflow = ''; }
    });
  </script>
