// Authentication Module for Done Delivery

class AuthManager {
    constructor() {
        this.currentUser = null;
        this.init();
    }

    init() {
        // Monitor auth state
        auth.onAuthStateChanged(async (user) => {
            if (user) {
                this.currentUser = user;
                await this.ensureUserProfile(user);
                this.updateUI(true);
            } else {
                this.currentUser = null;
                this.updateUI(false);
            }
        });
    }

    // Ensure user profile exists in Firestore
    async ensureUserProfile(user) {
        try {
            const userRef = db.collection('users').doc(user.uid);
            const userDoc = await userRef.get();

            if (!userDoc.exists) {
                // Create new user profile
                await userRef.set({
                    uid: user.uid,
                    email: user.email,
                    displayName: user.displayName || '',
                    firstName: '',
                    lastName: '',
                    phone: '',
                    whatsapp: '',
                    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                    role: 'customer', // customer, driver, admin
                    profileComplete: false
                }, { merge: true });
            }
        } catch (error) {
            console.error('Error ensuring user profile:', error);
        }
    }

    // Email/Password Sign Up
    async signUpWithEmail(email, password, userData) {
        try {
            // Create user account
            const userCredential = await auth.createUserWithEmailAndPassword(email, password);
            const user = userCredential.user;

            // Create user profile
            await db.collection('users').doc(user.uid).set({
                uid: user.uid,
                email: email,
                firstName: userData.firstName || '',
                lastName: userData.lastName || '',
                displayName: `${userData.firstName} ${userData.lastName}`.trim(),
                phone: userData.phone || '',
                whatsapp: userData.whatsapp || '',
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                role: 'customer',
                profileComplete: true
            });

            // Update display name
            await user.updateProfile({
                displayName: `${userData.firstName} ${userData.lastName}`.trim()
            });

            return { success: true, user: user };
        } catch (error) {
            console.error('Sign up error:', error);
            return { success: false, error: error.message };
        }
    }

    // Email/Password Sign In
    async signInWithEmail(email, password) {
        try {
            const userCredential = await auth.signInWithEmailAndPassword(email, password);
            return { success: true, user: userCredential.user };
        } catch (error) {
            console.error('Sign in error:', error);
            return { success: false, error: this.getErrorMessage(error.code) };
        }
    }

    // Google Sign In
    async signInWithGoogle() {
        try {
            const result = await auth.signInWithPopup(googleProvider);
            const user = result.user;

            // Check if user profile needs completion
            const userRef = db.collection('users').doc(user.uid);
            const userDoc = await userRef.get();
            const userData = userDoc.data();

            if (!userData.profileComplete) {
                // Show profile completion modal
                this.showProfileCompletionModal(user);
            }

            return { success: true, user: user, needsProfileCompletion: !userData.profileComplete };
        } catch (error) {
            console.error('Google sign in error:', error);
            return { success: false, error: error.message };
        }
    }

    // Complete user profile (for Google sign-in users)
    async completeProfile(userId, userData) {
        try {
            await db.collection('users').doc(userId).update({
                firstName: userData.firstName,
                lastName: userData.lastName,
                phone: userData.phone,
                whatsapp: userData.whatsapp,
                displayName: `${userData.firstName} ${userData.lastName}`.trim(),
                profileComplete: true,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });

            return { success: true };
        } catch (error) {
            console.error('Profile completion error:', error);
            return { success: false, error: error.message };
        }
    }

    // Sign Out
    async signOut() {
        try {
            await auth.signOut();
            this.currentUser = null;
            window.location.href = '/';
            return { success: true };
        } catch (error) {
            console.error('Sign out error:', error);
            return { success: false, error: error.message };
        }
    }

    // Password Reset
    async resetPassword(email) {
        try {
            await auth.sendPasswordResetEmail(email);
            return { success: true };
        } catch (error) {
            console.error('Password reset error:', error);
            return { success: false, error: this.getErrorMessage(error.code) };
        }
    }

    // Update UI based on auth state
    updateUI(isLoggedIn) {
        const authButtons = document.querySelectorAll('.auth-only');
        const guestButtons = document.querySelectorAll('.guest-only');
        const userDisplay = document.getElementById('userDisplay');

        authButtons.forEach(btn => {
            btn.style.display = isLoggedIn ? 'block' : 'none';
        });

        guestButtons.forEach(btn => {
            btn.style.display = isLoggedIn ? 'none' : 'block';
        });

        if (userDisplay && this.currentUser) {
            userDisplay.textContent = this.currentUser.displayName || this.currentUser.email;
        }
    }

    // Show profile completion modal
    showProfileCompletionModal(user) {
        const modal = document.getElementById('profileCompletionModal');
        if (modal) {
            modal.style.display = 'block';
            document.getElementById('profileEmail').value = user.email;
        }
    }

    // Get user-friendly error messages
    getErrorMessage(errorCode) {
        const messages = {
            'auth/email-already-in-use': 'This email is already registered. Please sign in instead.',
            'auth/invalid-email': 'Please enter a valid email address.',
            'auth/weak-password': 'Password should be at least 6 characters long.',
            'auth/user-not-found': 'No account found with this email.',
            'auth/wrong-password': 'Incorrect password. Please try again.',
            'auth/too-many-requests': 'Too many failed attempts. Please try again later.',
            'auth/network-request-failed': 'Network error. Please check your connection.',
            'auth/popup-closed-by-user': 'Sign-in cancelled.',
        };
        return messages[errorCode] || 'An error occurred. Please try again.';
    }

    // Get current user data
    async getCurrentUserData() {
        if (!this.currentUser) return null;

        try {
            const userDoc = await db.collection('users').doc(this.currentUser.uid).get();
            return userDoc.exists ? userDoc.data() : null;
        } catch (error) {
            console.error('Error getting user data:', error);
            return null;
        }
    }

    // Check if user is admin
    async isAdmin() {
        const userData = await this.getCurrentUserData();
        return userData && userData.role === 'admin';
    }

    // Check if user is driver
    async isDriver() {
        const userData = await this.getCurrentUserData();
        return userData && userData.role === 'driver';
    }
}

// Initialize Auth Manager
const authManager = new AuthManager();

