            const errors = this.validateParcelData(parcelData);
            if (errors.length > 0) {
                return { success: false, errors: errors };
            }

            // Get current user
            if (!authManager.currentUser) {
                return { success: false, error: 'User must be logged in' };
            }

            // Calculate cost
            const shippingCost = this.calculateShippingCost(parcelData.distance);

            // Prepare parcel document
            const parcel = {
                // Sender Information
                senderName: parcelData.senderName,
                senderPhone: parcelData.senderPhone,
                senderEmail: parcelData.senderEmail || '',
                senderAddress: parcelData.senderAddress,
                senderWhatsApp: parcelData.senderWhatsApp || parcelData.senderPhone,

                // Recipient Information
                recipientName: parcelData.recipientName,
                recipientPhone: parcelData.recipientPhone,
                recipientEmail: parcelData.recipientEmail || '',
                recipientAddress: parcelData.recipientAddress,
                recipientWhatsApp: parcelData.recipientWhatsApp || parcelData.recipientPhone,

                // Package Information
                packageDescription: parcelData.packageDescription,
                packageWeight: parcelData.packageWeight || '',
                packageDimensions: parcelData.packageDimensions || '',
                specialInstructions: parcelData.specialInstructions || '',

                // Delivery Information
                distance: parcelData.distance,
                shippingCost: shippingCost,
                serviceArea: this.SERVICE_AREA,

                // Tracking Information
                status: 'pending', // pending, picked_up, in_transit, delivered, cancelled
                statusHistory: [{
                    status: 'pending',
                    timestamp: firebase.firestore.FieldValue.serverTimestamp(),
                    note: 'Parcel created and awaiting payment'
                }],

                // Payment Information
                paymentStatus: paymentStatus, // pending, paid, failed
                paymentReference: '',
                paymentDate: null,

                // User Information
                userId: authManager.currentUser.uid,
                userEmail: authManager.currentUser.email,

                // Driver Information (assigned later)
                driverId: null,
                driverName: null,
                pickupTime: null,
                deliveryTime: null,
                deliveryProof: null,

                // Legal
                legalConfirmation: parcelData.legalConfirmation,
                legalConfirmationTime: firebase.firestore.FieldValue.serverTimestamp(),

                // Timestamps
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                updatedAt: firebase.firestore.FieldValue.serverTimestamp(),

                // Data retention (30 days in Firestore, forever in spreadsheet)
                expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // 30 days from now
                archivedToSheet: false
            };

            // Save to Firestore
            const docRef = await db.collection('parcels').add(parcel);
            const trackingId = docRef.id;

            // Update with tracking ID
            await docRef.update({
                trackingId: trackingId
            });

            return { 
                success: true, 
                trackingId: trackingId,
                shippingCost: shippingCost,
                parcelRef: docRef
            };

        } catch (error) {
            console.error('Error creating parcel:', error);
            return { success: false, error: error.message };
        }
    }

    // Update parcel status
    async updateParcelStatus(trackingId, newStatus, note = '', additionalData = {}) {
        try {
            const parcelRef = db.collection('parcels').doc(trackingId);
            const parcelDoc = await parcelRef.get();

            if (!parcelDoc.exists) {
                return { success: false, error: 'Parcel not found' };
            }

            const updateData = {
                status: newStatus,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
                statusHistory: firebase.firestore.FieldValue.arrayUnion({
                    status: newStatus,
                    timestamp: firebase.firestore.FieldValue.serverTimestamp(),
                    note: note,
                    updatedBy: authManager.currentUser ? authManager.currentUser.uid : 'system'
                }),
                ...additionalData
            };

            await parcelRef.update(updateData);

            // Get updated parcel data
            const updatedDoc = await parcelRef.get();
            const parcelData = updatedDoc.data();

            // Send notifications
            await this.sendStatusNotification(parcelData);

            // Archive to spreadsheet if delivered or cancelled
            if (newStatus === 'delivered' || newStatus === 'cancelled') {
                await this.archiveToSpreadsheet(trackingId, parcelData);
            }

            return { success: true, parcel: parcelData };

        } catch (error) {
            console.error('Error updating parcel status:', error);
            return { success: false, error: error.message };
        }
    }

    // Driver pickup confirmation
    async confirmPickup(trackingId, driverId, driverName) {
        return await this.updateParcelStatus(
            trackingId, 
            'picked_up', 
            'Package picked up by driver',
            {
                driverId: driverId,
                driverName: driverName,
                pickupTime: firebase.firestore.FieldValue.serverTimestamp()
            }
        );
    }

    // Start transit
    async startTransit(trackingId) {
        return await this.updateParcelStatus(
            trackingId,
            'in_transit',
            'Package is on the way to destination'
        );
    }

    // Confirm delivery with proof
    async confirmDelivery(trackingId, proofImageUrl, recipientSignature = '') {
        return await this.updateParcelStatus(
            trackingId,
            'delivered',
            'Package delivered successfully',
            {
                deliveryTime: firebase.firestore.FieldValue.serverTimestamp(),
                deliveryProof: proofImageUrl,
                recipientSignature: recipientSignature
            }
        );
    }

    // Get parcel by tracking ID
    async getParcel(trackingId) {
        try {
            const parcelDoc = await db.collection('parcels').doc(trackingId).get();

            if (!parcelDoc.exists) {
                return { success: false, error: 'Parcel not found' };
            }

            return { success: true, parcel: parcelDoc.data() };
        } catch (error) {
            console.error('Error getting parcel:', error);
            return { success: false, error: error.message };
        }
    }

    // Get user's parcels
    async getUserParcels(userId, limit = 50) {
        try {
            const snapshot = await db.collection('parcels')
                .where('userId', '==', userId)
                .orderBy('createdAt', 'desc')
                .limit(limit)
                .get();

            const parcels = [];
            snapshot.forEach(doc => {
                parcels.push({ id: doc.id, ...doc.data() });
            });

            return { success: true, parcels: parcels };
        } catch (error) {
            console.error('Error getting user parcels:', error);
            return { success: false, error: error.message };
        }
    }

    // Search parcels
    async searchParcels(query) {
        try {
            // Search by tracking ID
            const parcelDoc = await db.collection('parcels').doc(query).get();

            if (parcelDoc.exists) {
                return { success: true, parcels: [{ id: parcelDoc.id, ...parcelDoc.data() }] };
            }

            return { success: true, parcels: [] };
        } catch (error) {
            console.error('Error searching parcels:', error);
            return { success: false, error: error.message };
        }
    }

    // Send status notification (Email/SMS/WhatsApp)
    async sendStatusNotification(parcelData) {
        try {
            // Create notification document
            await db.collection('notifications').add({
                trackingId: parcelData.trackingId,
                recipientPhone: parcelData.recipientPhone,
                recipientEmail: parcelData.recipientEmail,
                recipientWhatsApp: parcelData.recipientWhatsApp,
                senderPhone: parcelData.senderPhone,
                senderEmail: parcelData.senderEmail,
                status: parcelData.status,
                message: this.getStatusMessage(parcelData.status, parcelData.trackingId),
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                sent: false
            });

            console.log('Notification queued for:', parcelData.trackingId);
        } catch (error) {
            console.error('Error queuing notification:', error);
        }
    }

    // Get status message for notifications
    getStatusMessage(status, trackingId) {
        const messages = {
            'pending': `Your parcel (${trackingId}) is pending. Awaiting payment confirmation.`,
            'picked_up': `Your parcel (${trackingId}) has been picked up by our driver from Venda.`,
            'in_transit': `Your parcel (${trackingId}) is on its way! It's being transported via our Express Road network.`,
            'delivered': `Your parcel (${trackingId}) has been delivered successfully! Thank you for using Done Delivery.`,
            'cancelled': `Your parcel (${trackingId}) has been cancelled.`
        };
        return messages[status] || `Status update for parcel ${trackingId}`;
    }

    // Archive to Google Spreadsheet (placeholder for Cloud Function)
    async archiveToSpreadsheet(trackingId, parcelData) {
        try {
            // This will be handled by a Cloud Function
            await db.collection('archive_queue').add({
                trackingId: trackingId,
                parcelData: parcelData,
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                processed: false
            });

            // Mark parcel as archived
            await db.collection('parcels').doc(trackingId).update({
                archivedToSheet: true
            });

            console.log('Parcel queued for archiving:', trackingId);
        } catch (error) {
            console.error('Error archiving to spreadsheet:', error);
        }
    }

    // Update payment status
    async updatePaymentStatus(trackingId, paymentReference, status = 'paid') {
        try {
            const updateData = {
                paymentStatus: status,
                paymentReference: paymentReference,
                paymentDate: firebase.firestore.FieldValue.serverTimestamp(),
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            };

            if (status === 'paid') {
                updateData.status = 'pending'; // Ready for pickup
                updateData.statusHistory = firebase.firestore.FieldValue.arrayUnion({
                    status: 'pending',
                    timestamp: firebase.firestore.FieldValue.serverTimestamp(),
                    note: 'Payment confirmed. Ready for pickup.'
                });
            }

            await db.collection('parcels').doc(trackingId).update(updateData);

            return { success: true };
        } catch (error) {
            console.error('Error updating payment status:', error);
            return { success: false, error: error.message };
        }
    }

    // Get status badge color
    getStatusBadgeClass(status) {
        const classes = {
            'pending': 'badge-warning',
            'picked_up': 'badge-info',
            'in_transit': 'badge-primary',
            'delivered': 'badge-success',
            'cancelled': 'badge-danger'
        };
        return classes[status] || 'badge-secondary';
    }

    // Get status display text
    getStatusDisplayText(status) {
        const texts = {
            'pending': 'Pending Pickup',
            'picked_up': 'Picked Up',
            'in_transit': 'In Transit',
            'delivered': 'Delivered',
            'cancelled': 'Cancelled'
        };
        return texts[status] || status;
    }

    // Format tracking ID for display
    formatTrackingId(trackingId) {
        return trackingId.toUpperCase();
    }

    // Calculate estimated delivery time
    getEstimatedDelivery() {
        // Same day delivery within Makhado
        const now = new Date();
        const delivery = new Date(now);
        delivery.setHours(now.getHours() + 24); // Within 24 hours
        return delivery.toLocaleString();
    }
}

