// PDF and Barcode Generator for Done Delivery

class PDFGenerator {
    constructor() {
        this.companyName = 'Done Delivery';
        this.companyPhone = '081 0606 488';
        this.primaryColor = '#E31E24'; // Red color from brand
    }

    // Generate customer receipt PDF
    async generateCustomerReceipt(parcelData, trackingId) {
        try {
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();

            // Company Header
            doc.setFillColor(227, 30, 36); // Red
            doc.rect(0, 0, 210, 40, 'F');

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(24);
            doc.setFont(undefined, 'bold');
            doc.text('done', 15, 20);
            doc.setFontSize(16);
            doc.text('DELIVERY', 15, 30);

            // Checkmark
            doc.setFontSize(40);
            doc.text('✓', 65, 28);

            // Receipt title
            doc.setTextColor(0, 0, 0);
            doc.setFontSize(18);
            doc.setFont(undefined, 'bold');
            doc.text('DELIVERY RECEIPT', 105, 55, { align: 'center' });

            // Tracking Information
            doc.setFontSize(12);
            doc.setFont(undefined, 'normal');
            doc.text('Tracking ID:', 15, 70);
            doc.setFont(undefined, 'bold');
            doc.setFontSize(14);
            doc.text(trackingId.toUpperCase(), 15, 78);

            // Generate and add barcode
            const canvas = document.createElement('canvas');
            JsBarcode(canvas, trackingId, {
                format: 'CODE128',
                width: 2,
                height: 50,
                displayValue: false
            });
            const barcodeImage = canvas.toDataURL('image/png');
            doc.addImage(barcodeImage, 'PNG', 15, 82, 80, 20);

            // Order Details
            doc.setFontSize(12);
            doc.setFont(undefined, 'bold');
            doc.text('ORDER DETAILS', 15, 115);
            doc.setLineWidth(0.5);
            doc.line(15, 117, 195, 117);

            doc.setFont(undefined, 'normal');
            doc.setFontSize(10);
            let yPos = 125;

            // Sender Information
            doc.setFont(undefined, 'bold');
            doc.text('From:', 15, yPos);
            doc.setFont(undefined, 'normal');
            yPos += 5;
            doc.text(parcelData.senderName, 15, yPos);
            yPos += 5;
            doc.text(parcelData.senderPhone, 15, yPos);
            yPos += 5;
            doc.text(parcelData.senderAddress, 15, yPos, { maxWidth: 85 });

            // Recipient Information
            yPos = 125;
            doc.setFont(undefined, 'bold');
            doc.text('To:', 110, yPos);
            doc.setFont(undefined, 'normal');
            yPos += 5;
            doc.text(parcelData.recipientName, 110, yPos);
            yPos += 5;
            doc.text(parcelData.recipientPhone, 110, yPos);
            yPos += 5;
            doc.text(parcelData.recipientAddress, 110, yPos, { maxWidth: 85 });

            // Package Information
            yPos = 165;
            doc.setFont(undefined, 'bold');
            doc.text('PACKAGE INFORMATION', 15, yPos);
            doc.line(15, yPos + 2, 195, yPos + 2);
            yPos += 8;

            doc.setFont(undefined, 'normal');
            doc.text('Description:', 15, yPos);
            doc.text(parcelData.packageDescription, 55, yPos, { maxWidth: 140 });
            yPos += 10;

            if (parcelData.packageWeight) {
                doc.text('Weight:', 15, yPos);
                doc.text(parcelData.packageWeight, 55, yPos);
                yPos += 7;
            }

            if (parcelData.specialInstructions) {
                doc.text('Special Instructions:', 15, yPos);
                doc.text(parcelData.specialInstructions, 55, yPos, { maxWidth: 140 });
                yPos += 10;
            }

            // Pricing
            yPos += 5;
            doc.setFont(undefined, 'bold');
            doc.text('PRICING', 15, yPos);
            doc.line(15, yPos + 2, 195, yPos + 2);
            yPos += 8;

            doc.setFont(undefined, 'normal');
            doc.text('Distance:', 15, yPos);
            doc.text(`${parcelData.distance} km`, 55, yPos);
            yPos += 7;

            doc.text('Rate:', 15, yPos);
            doc.text('R80 per km', 55, yPos);
            yPos += 7;

            doc.setFont(undefined, 'bold');
            doc.setFontSize(12);
            doc.text('Total:', 15, yPos);
            doc.text(`R ${parcelData.shippingCost}`, 55, yPos);

            // Delivery Timeline
            yPos += 15;
            doc.setFontSize(11);
            doc.text('EXPECTED DELIVERY', 15, yPos);
            doc.line(15, yPos + 2, 195, yPos + 2);
            yPos += 8;

            doc.setFontSize(9);
            doc.setFont(undefined, 'normal');
            doc.text('• Day 1 (0-5 hrs): Pickup from your door in Venda', 20, yPos);
            yPos += 6;
            doc.text('• Day 1 (5-7 hrs): Sorted and manifested via Express Road network', 20, yPos);
            yPos += 6;
            doc.text('• Day 1 (7-24 hrs): Delivery to doorstep in Makhado area', 20, yPos);

            // Footer
            doc.setFillColor(227, 30, 36);
            doc.rect(0, 270, 210, 27, 'F');

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(10);
            doc.text('Contact us: ' + this.companyPhone, 105, 280, { align: 'center' });
            doc.setFontSize(8);
            doc.text('WhatsApp • TikTok • Instagram • Facebook', 105, 287, { align: 'center' });
            doc.text('Thank you for choosing Done Delivery!', 105, 293, { align: 'center' });

            // Save PDF
            doc.save(`Done-Delivery-Receipt-${trackingId}.pdf`);

            return { success: true };
        } catch (error) {
            console.error('Error generating customer receipt:', error);
            return { success: false, error: error.message };
        }
    }

    // Generate shipping label for driver (sticker)
    async generateShippingLabel(parcelData, trackingId) {
        try {
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF({
                orientation: 'portrait',
                unit: 'mm',
                format: [100, 150] // 4x6 inch label
            });

            // Header with logo
            doc.setFillColor(227, 30, 36);
            doc.rect(0, 0, 100, 25, 'F');

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(16);
            doc.setFont(undefined, 'bold');
            doc.text('done', 5, 12);
            doc.setFontSize(11);
            doc.text('DELIVERY ✓', 5, 19);

            // Tracking ID and Barcode
            doc.setTextColor(0, 0, 0);
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('TRACKING ID', 5, 32);
            doc.setFontSize(12);
            doc.text(trackingId.toUpperCase(), 5, 38);

            // Generate barcode
            const canvas = document.createElement('canvas');
            JsBarcode(canvas, trackingId, {
                format: 'CODE128',
                width: 1.5,
                height: 35,
                displayValue: false,
                margin: 0
            });
            const barcodeImage = canvas.toDataURL('image/png');
            doc.addImage(barcodeImage, 'PNG', 5, 40, 90, 15);

            // Recipient Information (Large and clear)
            doc.setFontSize(9);
            doc.setFont(undefined, 'bold');
            doc.text('DELIVER TO:', 5, 62);

            doc.setFontSize(11);
            doc.setFont(undefined, 'bold');
            doc.text(parcelData.recipientName.toUpperCase(), 5, 68, { maxWidth: 90 });

            doc.setFontSize(10);
            doc.setFont(undefined, 'normal');
            doc.text(parcelData.recipientPhone, 5, 74);

            doc.setFontSize(9);
            const recipientLines = doc.splitTextToSize(parcelData.recipientAddress, 90);
            doc.text(recipientLines, 5, 80);

            // Sender Information
            const senderYPos = 80 + (recipientLines.length * 4) + 5;
            doc.setFontSize(8);
            doc.setFont(undefined, 'bold');
            doc.text('FROM:', 5, senderYPos);

            doc.setFont(undefined, 'normal');
            doc.text(parcelData.senderName, 5, senderYPos + 4);
            doc.text(parcelData.senderPhone, 5, senderYPos + 8);

            // Package Description
            const descYPos = senderYPos + 15;
            doc.setFont(undefined, 'bold');
            doc.text('CONTENTS:', 5, descYPos);
            doc.setFont(undefined, 'normal');
            const descLines = doc.splitTextToSize(parcelData.packageDescription, 90);
            doc.text(descLines, 5, descYPos + 4);

            // Footer with important info
            const footerY = 140;
            doc.setFillColor(227, 30, 36);
            doc.rect(0, footerY, 100, 10, 'F');
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(7);
            doc.text(`COST: R${parcelData.shippingCost}  |  ${parcelData.distance}km  |  ${this.companyPhone}`, 50, footerY + 6, { align: 'center' });

            // Save PDF
            doc.save(`Done-Delivery-Label-${trackingId}.pdf`);

            return { success: true };
        } catch (error) {
            console.error('Error generating shipping label:', error);
            return { success: false, error: error.message };
        }
    }

    // Generate both PDFs
    async generateBothDocuments(parcelData, trackingId) {
        try {
            await this.generateCustomerReceipt(parcelData, trackingId);
            // Small delay to prevent download conflicts
            await new Promise(resolve => setTimeout(resolve, 500));
            await this.generateShippingLabel(parcelData, trackingId);

            return { success: true };
        } catch (error) {
            console.error('Error generating documents:', error);
            return { success: false, error: error.message };
        }
    }

    // Generate barcode only (for display)
    generateBarcodeImage(trackingId, elementId) {
        try {
            const element = document.getElementById(elementId);
            if (!element) {
                console.error('Barcode element not found:', elementId);
                return;
            }

            JsBarcode(element, trackingId, {
                format: 'CODE128',
                width: 2,
                height: 60,
                displayValue: true,
                fontSize: 14,
                margin: 10
            });

            return { success: true };
        } catch (error) {
            console.error('Error generating barcode:', error);
            return { success: false, error: error.message };
        }
    }
}

// Initialize PDF Generator
const pdfGenerator = new PDFGenerator();

