// Paystack Payment Integration for Done Delivery

class PaymentManager {
    constructor() {
        // IMPORTANT: Replace with your actual Paystack public key
        this.publicKey = 'pk_test_your_public_key_here'; // TODO: Add real Paystack public key
        this.handler = null;
    }

    // Initialize Paystack payment
    async initiatePayment(parcelData, trackingId, amount) {
        try {
            if (!window.PaystackPop) {
                throw new Error('Paystack library not loaded');
            }

            // Get current user
            if (!authManager.currentUser) {
                throw new Error('User must be logged in');
            }

            const email = authManager.currentUser.email;
            const amountInKobo = amount * 100; // Convert to kobo

            // Initialize Paystack
            this.handler = PaystackPop.setup({
                key: this.publicKey,
                email: email,
                amount: amountInKobo,
                currency: 'ZAR',
                ref: this.generateReference(trackingId),
                metadata: {
                    custom_fields: [
                        {
                            display_name: 'Tracking ID',
                            variable_name: 'tracking_id',
                            value: trackingId
                        },
                        {
                            display_name: 'Customer Name',
                            variable_name: 'customer_name',
                            value: parcelData.senderName
                        },
                        {
                            display_name: 'Service',
                            variable_name: 'service',
                            value: 'Parcel Delivery'
                        }
                    ]
                },
                callback: async (response) => {
                    await this.handlePaymentSuccess(response, trackingId);
                },
                onClose: () => {
                    this.handlePaymentClose(trackingId);
                }
            });

            // Open payment modal
            this.handler.openIframe();

            return { success: true };

        } catch (error) {
            console.error('Error initiating payment:', error);
            return { success: false, error: error.message };
        }
    }

    // Handle successful payment
    async handlePaymentSuccess(response, trackingId) {
        try {
            console.log('Payment successful:', response);

            // Update parcel payment status
            await parcelManager.updatePaymentStatus(
                trackingId,
                response.reference,
                'paid'
            );

            // Show success message
            this.showPaymentSuccess(trackingId, response.reference);

            // Generate PDFs
            const parcelResult = await parcelManager.getParcel(trackingId);
            if (parcelResult.success) {
                await pdfGenerator.generateBothDocuments(
                    parcelResult.parcel,
                    trackingId
                );
            }

            // Send confirmation notifications
            await this.sendPaymentConfirmation(trackingId, response.reference);

            // Redirect to tracking page after 3 seconds
            setTimeout(() => {
                window.location.href = `/pages/track.html?id=${trackingId}`;
            }, 3000);

        } catch (error) {
            console.error('Error handling payment success:', error);
            this.showPaymentError('Payment successful but confirmation failed. Please contact support.');
        }
    }

    // Handle payment modal close
    handlePaymentClose(trackingId) {
        console.log('Payment modal closed');

        // Show message that payment was cancelled
        const message = document.createElement('div');
        message.className = 'alert alert-warning';
        message.innerHTML = `
            <strong>Payment Cancelled</strong><br>
            You can complete payment later using tracking ID: <strong>${trackingId}</strong>
        `;

        const container = document.getElementById('paymentMessages');
        if (container) {
            container.appendChild(message);
        }
    }

    // Show payment success message
    showPaymentSuccess(trackingId, reference) {
        const message = document.createElement('div');
        message.className = 'alert alert-success payment-success';
        message.innerHTML = `
            <div class="success-animation">
                <svg class="checkmark" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 52 52">
                    <circle class="checkmark-circle" cx="26" cy="26" r="25" fill="none"/>
                    <path class="checkmark-check" fill="none" d="M14.1 27.2l7.1 7.2 16.7-16.8"/>
                </svg>
            </div>
            <h3>Payment Successful!</h3>
            <p>Your payment has been received.</p>
            <p><strong>Tracking ID:</strong> ${trackingId}</p>
            <p><strong>Reference:</strong> ${reference}</p>
            <p>Your parcel receipt and shipping label are being downloaded...</p>
            <p class="redirect-msg">Redirecting to tracking page...</p>
        `;

        const container = document.getElementById('paymentMessages');
        if (container) {
            container.innerHTML = '';
            container.appendChild(message);
        }
    }

    // Show payment error message
    showPaymentError(errorMessage) {
        const message = document.createElement('div');
        message.className = 'alert alert-danger';
        message.innerHTML = `
            <strong>Payment Error</strong><br>
            ${errorMessage}
        `;

        const container = document.getElementById('paymentMessages');
        if (container) {
            container.appendChild(message);
        }
    }

    // Generate unique payment reference
    generateReference(trackingId) {
        const timestamp = Date.now();
        return `DD-${trackingId.substring(0, 8)}-${timestamp}`;
    }

    // Send payment confirmation
    async sendPaymentConfirmation(trackingId, reference) {
        try {
            await db.collection('notifications').add({
                type: 'payment_confirmation',
                trackingId: trackingId,
                paymentReference: reference,
                userId: authManager.currentUser.uid,
                email: authManager.currentUser.email,
                message: `Payment confirmed for parcel ${trackingId}. Reference: ${reference}`,
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                sent: false
            });
        } catch (error) {
            console.error('Error sending payment confirmation:', error);
        }
    }

    // Verify payment (backend verification)
    async verifyPayment(reference) {
        try {
            // This should be done on the backend with secret key
            // For now, we'll just check Firestore
            const parcelsRef = db.collection('parcels');
            const query = await parcelsRef
                .where('paymentReference', '==', reference)
                .limit(1)
                .get();

            if (!query.empty) {
                const parcel = query.docs[0].data();
                return {
                    success: true,
                    verified: parcel.paymentStatus === 'paid',
                    parcel: parcel
                };
            }

            return { success: false, error: 'Payment not found' };

        } catch (error) {
            console.error('Error verifying payment:', error);
            return { success: false, error: error.message };
        }
    }

    // Pay for existing parcel
    async payForParcel(trackingId) {
        try {
            const result = await parcelManager.getParcel(trackingId);

            if (!result.success) {
                return { success: false, error: 'Parcel not found' };
            }

            const parcel = result.parcel;

            if (parcel.paymentStatus === 'paid') {
                return { success: false, error: 'Parcel already paid for' };
            }

            return await this.initiatePayment(parcel, trackingId, parcel.shippingCost);

        } catch (error) {
            console.error('Error paying for parcel:', error);
            return { success: false, error: error.message };
        }
    }
}

// Initialize Payment Manager
const paymentManager = new PaymentManager();

