            </ul>
        </div>
    </nav>

    <!-- Auth Container -->
    <div class="auth-container">
        <div class="card">
            <!-- Tabs -->
            <div class="auth-tabs">
                <button class="auth-tab active" data-tab="login">Login</button>
                <button class="auth-tab" data-tab="register">Register</button>
            </div>

            <!-- Messages -->
            <div id="authMessages"></div>

            <!-- Login Form -->
            <div class="auth-form active" id="loginForm">
                <h2 class="card-title">Welcome Back!</h2>
                <p class="mb-3">Login to track and manage your parcels.</p>

                <form id="loginEmailForm">
                    <div class="form-group">
                        <label for="loginEmail">Email Address</label>
                        <input type="email" id="loginEmail" class="form-control" required>
                    </div>

                    <div class="form-group password-toggle">
                        <label for="loginPassword">Password</label>
                        <input type="password" id="loginPassword" class="form-control" required>
                        <button type="button" class="password-toggle-btn" onclick="togglePassword('loginPassword')">
                            👁️
                        </button>
                    </div>

                    <button type="submit" class="btn btn-primary btn-block">Login</button>
                </form>

                <div class="divider">
                    <span>OR</span>
                </div>

                <button class="google-btn" id="googleLoginBtn">
                    <svg width="18" height="18" xmlns="http://www.w3.org/2000/svg"><g fill="#000" fill-rule="evenodd"><path d="M9 3.48c1.69 0 2.83.73 3.48 1.34l2.54-2.48C13.46.89 11.43 0 9 0 5.48 0 2.44 2.02.96 4.96l2.91 2.26C4.6 5.05 6.62 3.48 9 3.48z" fill="#EA4335"></path><path d="M17.64 9.2c0-.74-.06-1.28-.19-1.84H9v3.34h4.96c-.1.83-.64 2.08-1.84 2.92l2.84 2.2c1.7-1.57 2.68-3.88 2.68-6.62z" fill="#4285F4"></path><path d="M3.88 10.78A5.54 5.54 0 0 1 3.58 9c0-.62.11-1.22.29-1.78L.96 4.96A9.008 9.008 0 0 0 0 9c0 1.45.35 2.82.96 4.04l2.92-2.26z" fill="#FBBC05"></path><path d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.84-2.2c-.76.53-1.78.9-3.12.9-2.38 0-4.4-1.57-5.12-3.74L.97 13.04C2.45 15.98 5.48 18 9 18z" fill="#34A853"></path><path fill="none" d="M0 0h18v18H0z"></path></g></svg>
                    Continue with Google
                </button>

                <p class="text-center mt-3">
                    <a href="#" id="forgotPasswordLink">Forgot password?</a>
                </p>
            </div>

            <!-- Register Form -->
            <div class="auth-form" id="registerForm">
                <h2 class="card-title">Create Account</h2>
                <p class="mb-3">Start sending parcels today!</p>

                <form id="registerEmailForm">
                    <div class="form-row">
                        <div class="form-group">
                            <label for="registerFirstName">First Name *</label>
                            <input type="text" id="registerFirstName" class="form-control" required>
                        </div>

                        <div class="form-group">
                            <label for="registerLastName">Last Name *</label>
                            <input type="text" id="registerLastName" class="form-control" required>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="registerEmail">Email Address *</label>
                        <input type="email" id="registerEmail" class="form-control" required>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label for="registerPhone">Phone Number *</label>
                            <input type="tel" id="registerPhone" class="form-control" placeholder="0821234567" required>
                        </div>

                        <div class="form-group">
                            <label for="registerWhatsApp">WhatsApp Number *</label>
                            <input type="tel" id="registerWhatsApp" class="form-control" placeholder="0821234567" required>
                        </div>
                    </div>

                    <div class="form-group password-toggle">
                        <label for="registerPassword">Password *</label>
                        <input type="password" id="registerPassword" class="form-control" minlength="6" required>
                        <button type="button" class="password-toggle-btn" onclick="togglePassword('registerPassword')">
                            👁️
