            </div>

            <p>Please complete your profile to continue.</p>

            <form id="profileCompletionForm">
                <div class="form-group">
                    <label>Email</label>
                    <input type="email" id="profileEmail" class="form-control" disabled>
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label for="profileFirstName">First Name *</label>
                        <input type="text" id="profileFirstName" class="form-control" required>
                    </div>

                    <div class="form-group">
                        <label for="profileLastName">Last Name *</label>
                        <input type="text" id="profileLastName" class="form-control" required>
                    </div>
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label for="profilePhone">Phone Number *</label>
                        <input type="tel" id="profilePhone" class="form-control" required>
                    </div>

                    <div class="form-group">
                        <label for="profileWhatsApp">WhatsApp *</label>
                        <input type="tel" id="profileWhatsApp" class="form-control" required>
                    </div>
                </div>

                <button type="submit" class="btn btn-primary btn-block">Complete Profile</button>
            </form>
        </div>
    </div>

    <!-- Password Reset Modal -->
    <div class="modal" id="resetPasswordModal">
        <div class="modal-content">
            <div class="modal-header">
                <h3>Reset Password</h3>
                <button class="modal-close" onclick="closeModal('resetPasswordModal')">&times;</button>
            </div>

            <div id="resetMessages"></div>

            <form id="resetPasswordForm">
                <div class="form-group">
                    <label for="resetEmail">Enter your email address</label>
                    <input type="email" id="resetEmail" class="form-control" required>
                    <small>We'll send you a link to reset your password.</small>
                </div>

                <button type="submit" class="btn btn-primary btn-block">Send Reset Link</button>
            </form>
        </div>
    </div>

    <!-- Scripts -->
    <script src="/js/firebase-config.js"></script>
    <script src="/js/auth.js"></script>
    <script>
        // Tab switching
        document.querySelectorAll('.auth-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                const tabName = tab.dataset.tab;

                // Update active tab
                document.querySelectorAll('.auth-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');

                // Show corresponding form
                document.querySelectorAll('.auth-form').forEach(form => form.classList.remove('active'));
                document.getElementById(tabName + 'Form').classList.add('active');

                // Clear messages
                document.getElementById('authMessages').innerHTML = '';
            });
        });

        // Login with Email
        document.getElementById('loginEmailForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const email = document.getElementById('loginEmail').value;
            const password = document.getElementById('loginPassword').value;

            showLoading();

            const result = await authManager.signInWithEmail(email, password);

            hideLoading();

            if (result.success) {
                showMessage('Login successful! Redirecting...', 'success');
                setTimeout(() => {
                    window.location.href = '/pages/create-parcel.html';
                }, 1500);
            } else {
                showMessage(result.error, 'danger');
            }
        });

        // Register with Email
        document.getElementById('registerEmailForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const password = document.getElementById('registerPassword').value;
            const confirmPassword = document.getElementById('registerConfirmPassword').value;

            if (password !== confirmPassword) {
                showMessage('Passwords do not match!', 'danger');
                return;
            }

            const userData = {
                firstName: document.getElementById('registerFirstName').value,
                lastName: document.getElementById('registerLastName').value,
                phone: document.getElementById('registerPhone').value,
                whatsapp: document.getElementById('registerWhatsApp').value
            };

            const email = document.getElementById('registerEmail').value;

            showLoading();

            const result = await authManager.signUpWithEmail(email, password, userData);

            hideLoading();

            if (result.success) {
                showMessage('Account created successfully! Redirecting...', 'success');
                setTimeout(() => {
                    window.location.href = '/pages/create-parcel.html';
                }, 1500);
            } else {
                showMessage(result.error, 'danger');
            }
        });

        // Google Sign In (Login)
        document.getElementById('googleLoginBtn').addEventListener('click', async () => {
            showLoading();
            const result = await authManager.signInWithGoogle();
            hideLoading();

            if (result.success) {
                if (result.needsProfileCompletion) {
                    // Profile completion modal will be shown by authManager
                } else {
                    window.location.href = '/pages/create-parcel.html';
                }
            } else {
                showMessage(result.error, 'danger');
            }
        });

        // Google Sign In (Register)
        document.getElementById('googleRegisterBtn').addEventListener('click', async () => {
            showLoading();
            const result = await authManager.signInWithGoogle();
            hideLoading();

            if (result.success) {
                if (result.needsProfileCompletion) {
                    // Profile completion modal will be shown
                } else {
                    window.location.href = '/pages/create-parcel.html';
                }
            } else {
                showMessage(result.error, 'danger');
            }
        });

        // Profile Completion
        document.getElementById('profileCompletionForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const userData = {
                firstName: document.getElementById('profileFirstName').value,
                lastName: document.getElementById('profileLastName').value,
                phone: document.getElementById('profilePhone').value,
                whatsapp: document.getElementById('profileWhatsApp').value
            };

            showLoading();

            const result = await authManager.completeProfile(authManager.currentUser.uid, userData);

            hideLoading();

            if (result.success) {
                document.getElementById('profileCompletionModal').style.display = 'none';
                window.location.href = '/pages/create-parcel.html';
            } else {
                showMessage(result.error, 'danger');
            }
        });

        // Forgot Password
        document.getElementById('forgotPasswordLink').addEventListener('click', (e) => {
            e.preventDefault();
            document.getElementById('resetPasswordModal').classList.add('active');
        });

        document.getElementById('resetPasswordForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const email = document.getElementById('resetEmail').value;

            const result = await authManager.resetPassword(email);

            if (result.success) {
                showResetMessage('Password reset link sent! Check your email.', 'success');
                setTimeout(() => {
                    closeModal('resetPasswordModal');
                }, 3000);
            } else {
                showResetMessage(result.error, 'danger');
            }
        });

        // Helper functions
        function togglePassword(inputId) {
            const input = document.getElementById(inputId);
            input.type = input.type === 'password' ? 'text' : 'password';
        }

        function showMessage(message, type) {
            const messagesDiv = document.getElementById('authMessages');
            messagesDiv.innerHTML = `<div class="alert alert-${type}">${message}</div>`;
        }

        function showResetMessage(message, type) {
            const messagesDiv = document.getElementById('resetMessages');
            messagesDiv.innerHTML = `<div class="alert alert-${type}">${message}</div>`;
        }

        function closeModal(modalId) {
            document.getElementById(modalId).classList.remove('active');
        }

        function showLoading() {
            const overlay = document.createElement('div');
            overlay.className = 'loading-overlay';
            overlay.id = 'loadingOverlay';
            overlay.innerHTML = '<div class="loading"></div>';
            document.body.appendChild(overlay);
        }

        function hideLoading() {
            const overlay = document.getElementById('loadingOverlay');
            if (overlay) overlay.remove();
        }

        // Check if user is already logged in
        auth.onAuthStateChanged(user => {
            if (user) {
                window.location.href = '/pages/create-parcel.html';
            }
        });
    </script>
</body>
</html>
