/* ===================================
   RESET & VARIABLES
   =================================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Primary Colors - Vibrant African palette */
    --primary-orange: #FF6B35;
    --primary-yellow: #F7931E;
    --primary-teal: #4ECDC4;
    --primary-coral: #FF8B94;
    --primary-green: #00B894;
    --primary-purple: #6C5CE7;

    /* Secondary Colors */
    --secondary-light: #FFD3B6;
    --secondary-mint: #A8E6CF;
    --secondary-lavender: #A29BFE;
    --secondary-peach: #FAB1A0;

    /* Neutral Colors */
    --dark: #2D3436;
    --dark-light: #636E72;
    --light: #F8F9FA;
    --white: #FFFFFF;
    --gray: #DFE6E9;

    /* Gradients */
    --gradient-sunset: linear-gradient(135deg, #FF6B35 0%, #F7931E 100%);
    --gradient-ocean: linear-gradient(135deg, #4ECDC4 0%, #00B894 100%);
    --gradient-purple: linear-gradient(135deg, #6C5CE7 0%, #A29BFE 100%);

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;

    /* Typography */
    --font-primary: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    --font-heading: 'Georgia', serif;

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-medium: 0.4s ease;
    --transition-slow: 0.6s ease;
}

/* ===================================
   GLOBAL STYLES
   =================================== */

html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}

body {
    font-family: var(--font-primary);
    color: var(--dark);
    line-height: 1.6;
    overflow-x: hidden;
    background-color: var(--light);
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    text-decoration: none;
    color: inherit;
}

/* ===================================
   NAVIGATION
   =================================== */

.navbar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background: var(--white);
    box-shadow: 0 2px 20px rgba(0, 0, 0, 0.1);
    z-index: 1000;
    padding: 1rem 0;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-family: var(--font-heading);
    font-size: 2rem;
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.2rem;
}

.logo .tagline {
    font-size: 0.75rem;
    color: var(--dark-light);
    text-transform: uppercase;
    letter-spacing: 2px;
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
    align-items: center;
}

.nav-link {
    color: var(--dark);
    font-weight: 500;
    position: relative;
    padding: 0.5rem 0;
    transition: color var(--transition-fast);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-sunset);
    transition: width var(--transition-medium);
}

.nav-link:hover,
.nav-link.active {
    color: var(--primary-orange);
}

.nav-link:hover::after,
.nav-link.active::after {
    width: 100%;
}

/* Hamburger Menu */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 0.4rem;
}

.hamburger span {
    width: 30px;
    height: 3px;
    background: var(--dark);
    border-radius: 3px;
    transition: all var(--transition-medium);
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(8px, -8px);
}

/* ===================================
   HERO SECTION
   =================================== */

.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    padding-top: 80px;
}

.hero-content {
    text-align: center;
    max-width: 800px;
    z-index: 2;
    padding: var(--spacing-md);
}

.hero-title {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    margin-bottom: var(--spacing-md);
    color: var(--dark);
    line-height: 1.2;
}

.hero-subtitle {
    font-size: clamp(1rem, 2vw, 1.3rem);
    color: var(--dark-light);
    margin-bottom: var(--spacing-lg);
    line-height: 1.8;
}

.hero-buttons {
    display: flex;
    gap: var(--spacing-md);
    justify-content: center;
    flex-wrap: wrap;
}

/* Buttons */
.btn {
    padding: 1rem 2.5rem;
    border-radius: 50px;
    font-weight: 600;
    font-size: 1rem;
    cursor: pointer;
    transition: all var(--transition-medium);
    border: none;
    display: inline-block;
    text-align: center;
}

.btn-primary {
    background: var(--gradient-sunset);
    color: var(--white);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.3);
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(255, 107, 53, 0.4);
}

.btn-secondary {
    background: transparent;
    color: var(--dark);
    border: 2px solid var(--primary-orange);
}

.btn-secondary:hover {
    background: var(--primary-orange);
    color: var(--white);
    transform: translateY(-3px);
}

/* Floating Shapes */
.hero-visual {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
}

.floating-shape {
    position: absolute;
    border-radius: 50%;
    opacity: 0.6;
}

.shape-1 {
    width: 300px;
    height: 300px;
    background: var(--gradient-sunset);
    top: 10%;
    left: -10%;
}

.shape-2 {
    width: 200px;
    height: 200px;
    background: var(--gradient-ocean);
    bottom: 20%;
    right: -5%;
}

.shape-3 {
    width: 150px;
    height: 150px;
    background: var(--gradient-purple);
    top: 60%;
    left: 10%;
}

.shape-4 {
    width: 100px;
    height: 100px;
    background: var(--primary-coral);
    top: 30%;
    right: 15%;
}

/* Scroll Indicator */
.scroll-indicator {
    position: absolute;
    bottom: 40px;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    z-index: 2;
}

.scroll-indicator span {
    display: block;
    font-size: 0.9rem;
    color: var(--dark-light);
    margin-bottom: 0.5rem;
}

.scroll-arrow {
    width: 30px;
    height: 50px;
    border: 2px solid var(--primary-orange);
    border-radius: 20px;
    margin: 0 auto;
    position: relative;
}

.scroll-arrow::after {
    content: '';
    position: absolute;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    height: 6px;
    background: var(--primary-orange);
    border-radius: 50%;
    animation: scroll-down 2s infinite;
}

@keyframes scroll-down {
    0%, 100% { top: 10px; opacity: 1; }
    50% { top: 25px; opacity: 0.5; }
}

/* ===================================
   SECTION HEADERS
   =================================== */

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-lg);
}

.section-title {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 4vw, 3rem);
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.title-underline {
    width: 100px;
    height: 4px;
    background: var(--gradient-sunset);
    margin: 0 auto;
    border-radius: 2px;
}

.section-description {
    font-size: 1.1rem;
    color: var(--dark-light);
    margin-top: var(--spacing-md);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* ===================================
   ABOUT SECTION
   =================================== */

.about {
    padding: var(--spacing-xl) 0;
    background: var(--white);
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.about-text h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.about-text p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark-light);
    line-height: 1.8;
}

.about-text h4 {
    font-size: 1.5rem;
    margin-top: var(--spacing-lg);
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.about-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-md);
    margin: var(--spacing-lg) 0;
}

.stat-item {
    text-align: center;
    padding: var(--spacing-md);
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    border-radius: 15px;
}

.stat-number {
    display: block;
    font-size: 2.5rem;
    font-weight: 700;
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
}

.stat-label {
    display: block;
    font-size: 0.9rem;
    color: var(--dark-light);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.process-list {
    list-style: none;
    margin-top: var(--spacing-md);
}

.process-list li {
    padding: var(--spacing-sm) 0;
    padding-left: 2rem;
    position: relative;
    color: var(--dark-light);
    font-size: 1.05rem;
}

.process-list li::before {
    content: '→';
    position: absolute;
    left: 0;
    color: var(--primary-orange);
    font-size: 1.5rem;
    font-weight: 700;
}

.process-list li strong {
    color: var(--dark);
}

.about-image {
    position: relative;
}

.image-placeholder {
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.image-placeholder svg {
    width: 100%;
    height: auto;
}

/* ===================================
   CATALOG/GALLERY SECTION
   =================================== */

.catalog {
    padding: var(--spacing-xl) 0;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
}

.gallery-filters {
    display: flex;
    justify-content: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
    flex-wrap: wrap;
}

.filter-btn {
    padding: 0.75rem 2rem;
    border: 2px solid var(--primary-orange);
    background: transparent;
    color: var(--dark);
    border-radius: 50px;
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.filter-btn:hover,
.filter-btn.active {
    background: var(--gradient-sunset);
    color: var(--white);
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.3);
}

.gallery-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--spacing-md);
}

.gallery-item {
    background: var(--white);
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: all var(--transition-medium);
    cursor: pointer;
}

.gallery-item:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15);
}

.gallery-image {
    width: 100%;
    height: 300px;
    overflow: hidden;
    position: relative;
}

.gallery-image svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.gallery-item:hover .gallery-image svg {
    transform: scale(1.1);
}

.gallery-info {
    padding: var(--spacing-md);
}

.gallery-info h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
    color: var(--dark);
}

.gallery-info p {
    color: var(--dark-light);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-sm);
}

.view-details {
    color: var(--primary-orange);
    font-weight: 600;
    font-size: 0.9rem;
    display: inline-block;
    position: relative;
}

.view-details::after {
    content: ' →';
    transition: transform var(--transition-fast);
    display: inline-block;
}

.gallery-item:hover .view-details::after {
    transform: translateX(5px);
}

/* ===================================
   CONTACT SECTION
   =================================== */

.contact {
    padding: var(--spacing-xl) 0;
    background: var(--white);
}

.contact-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xl);
}

.contact-info h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.contact-info > p {
    color: var(--dark-light);
    margin-bottom: var(--spacing-lg);
    line-height: 1.8;
}

.info-items {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

.info-item {
    display: flex;
    gap: var(--spacing-md);
    align-items: flex-start;
}

.info-icon {
    font-size: 2rem;
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    border-radius: 15px;
    flex-shrink: 0;
}

.info-text h4 {
    font-size: 1.1rem;
    margin-bottom: 0.3rem;
    color: var(--dark);
}

.info-text p {
    color: var(--dark-light);
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.social-link {
    padding: 0.75rem 1.5rem;
    background: var(--gradient-sunset);
    color: var(--white);
    border-radius: 50px;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.social-link:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(255, 107, 53, 0.4);
}

/* Contact Form */
.contact-form-wrapper {
    position: relative;
}

.contact-form {
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    padding: var(--spacing-lg);
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.form-group {
    margin-bottom: var(--spacing-md);
    position: relative;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 1rem;
    border: 2px solid var(--gray);
    border-radius: 10px;
    font-size: 1rem;
    font-family: var(--font-primary);
    transition: all var(--transition-medium);
    background: var(--white);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--primary-orange);
}

.form-group label {
    position: absolute;
    top: 1rem;
    left: 1rem;
    color: var(--dark-light);
    pointer-events: none;
    transition: all var(--transition-medium);
    background: var(--white);
    padding: 0 0.5rem;
}

.form-group input:focus + label,
.form-group textarea:focus + label,
.form-group select:focus + label,
.form-group input:not(:placeholder-shown) + label,
.form-group textarea:not(:placeholder-shown) + label,
.form-group select:valid + label {
    top: -0.5rem;
    left: 0.75rem;
    font-size: 0.85rem;
    color: var(--primary-orange);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
    opacity: 0;
}

.btn-submit {
    width: 100%;
    margin-top: var(--spacing-md);
}

.form-success {
    display: none;
    text-align: center;
    padding: var(--spacing-lg);
    background: var(--white);
    border-radius: 20px;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 100%;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.form-success.show {
    display: block;
}

.success-icon {
    width: 80px;
    height: 80px;
    background: var(--gradient-sunset);
    color: var(--white);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    margin: 0 auto var(--spacing-md);
}

.form-success h3 {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.form-success p {
    color: var(--dark-light);
}

/* ===================================
   PRIVACY SECTION
   =================================== */

.privacy {
    padding: var(--spacing-xl) 0;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
}

.privacy-content {
    max-width: 900px;
    margin: 0 auto;
    background: var(--white);
    padding: var(--spacing-lg);
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.last-updated {
    color: var(--dark-light);
    font-style: italic;
    margin-bottom: var(--spacing-lg);
}

.privacy-section {
    margin-bottom: var(--spacing-lg);
}

.privacy-section h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.privacy-section p {
    color: var(--dark-light);
    line-height: 1.8;
    margin-bottom: var(--spacing-sm);
}

.privacy-section ul {
    list-style: none;
    margin-top: var(--spacing-md);
}

.privacy-section ul li {
    padding: 0.5rem 0;
    padding-left: 2rem;
    position: relative;
    color: var(--dark-light);
}

.privacy-section ul li::before {
    content: '•';
    position: absolute;
    left: 0.75rem;
    color: var(--primary-orange);
    font-size: 1.5rem;
}

/* ===================================
   FOOTER
   =================================== */

.footer {
    background: var(--dark);
    color: var(--white);
    padding: var(--spacing-lg) 0 var(--spacing-md);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-brand h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.footer-brand p {
    color: var(--gray);
    line-height: 1.8;
}

.footer-links h4 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-md);
    color: var(--white);
}

.footer-links ul {
    list-style: none;
}

.footer-links ul li {
    margin-bottom: 0.75rem;
}

.footer-links ul li a {
    color: var(--gray);
    transition: color var(--transition-fast);
}

.footer-links ul li a:hover {
    color: var(--primary-orange);
}

.footer-newsletter h4 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-md);
    color: var(--white);
}

.footer-newsletter p {
    color: var(--gray);
    margin-bottom: var(--spacing-md);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border: none;
    border-radius: 50px;
    font-size: 0.95rem;
}

.newsletter-form button {
    padding: 0.75rem 1.5rem;
    background: var(--gradient-sunset);
    color: var(--white);
    border: none;
    border-radius: 50px;
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.newsletter-form button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.4);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-bottom p {
    color: var(--gray);
}

/* ===================================
   RESPONSIVE DESIGN
   =================================== */

@media (max-width: 968px) {
    .nav-menu {
        position: fixed;
        left: -100%;
        top: 70px;
        flex-direction: column;
        background: var(--white);
        width: 100%;
        text-align: center;
        transition: left var(--transition-medium);
        box-shadow: 0 10px 27px rgba(0, 0, 0, 0.05);
        padding: var(--spacing-md) 0;
        gap: 0;
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-menu li {
        margin: 1rem 0;
    }

    .hamburger {
        display: flex;
    }

    .about-content,
    .contact-content {
        grid-template-columns: 1fr;
    }

    .about-stats {
        grid-template-columns: 1fr;
    }

    .hero-buttons {
        flex-direction: column;
        align-items: center;
    }

    .btn {
        width: 100%;
        max-width: 300px;
    }

    .gallery-grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    }
}

@media (max-width: 768px) {
    :root {
        --spacing-lg: 3rem;
        --spacing-xl: 4rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .gallery-filters {
        justify-content: flex-start;
        overflow-x: auto;
        padding-bottom: var(--spacing-sm);
    }

    .filter-btn {
        white-space: nowrap;
    }

    .footer-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .floating-shape {
        opacity: 0.3;
    }
}

@media (max-width: 480px) {
    .logo h1 {
        font-size: 1.5rem;
    }

    .gallery-grid {
        grid-template-columns: 1fr;
    }

    .contact-form {
        padding: var(--spacing-md);
    }
}

/* ===================================
   UTILITY CLASSES
   =================================== */

.hidden {
    display: none;
}

.fade-in {
    opacity: 0;
    animation: fadeIn 0.8s forwards;
}

@keyframes fadeIn {
    to {
        opacity: 1;
    }
}

/* Smooth scrolling for all browsers */
@media (prefers-reduced-motion: no-preference) {
    html {
        scroll-behavior: smooth;
    }
}

display_content.json_block:
{"language": "css", "code": "/* ===================================
   RESET & VARIABLES
   =================================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Primary Colors - Vibrant African palette */
    --primary-orange: #FF6B35;
    --primary-yellow: #F7931E;
    --primary-teal: #4ECDC4;
    --primary-coral: #FF8B94;
    --primary-green: #00B894;
    --primary-purple: #6C5CE7;

    /* Secondary Colors */
    --secondary-light: #FFD3B6;
    --secondary-mint: #A8E6CF;
    --secondary-lavender: #A29BFE;
    --secondary-peach: #FAB1A0;

    /* Neutral Colors */
    --dark: #2D3436;
    --dark-light: #636E72;
    --light: #F8F9FA;
    --white: #FFFFFF;
    --gray: #DFE6E9;

    /* Gradients */
    --gradient-sunset: linear-gradient(135deg, #FF6B35 0%, #F7931E 100%);
    --gradient-ocean: linear-gradient(135deg, #4ECDC4 0%, #00B894 100%);
    --gradient-purple: linear-gradient(135deg, #6C5CE7 0%, #A29BFE 100%);

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;

    /* Typography */
    --font-primary: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    --font-heading: 'Georgia', serif;

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-medium: 0.4s ease;
    --transition-slow: 0.6s ease;
}

/* ===================================
   GLOBAL STYLES
   =================================== */

html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}

body {
    font-family: var(--font-primary);
    color: var(--dark);
    line-height: 1.6;
    overflow-x: hidden;
    background-color: var(--light);
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    text-decoration: none;
    color: inherit;
}

/* ===================================
   NAVIGATION
   =================================== */

.navbar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background: var(--white);
    box-shadow: 0 2px 20px rgba(0, 0, 0, 0.1);
    z-index: 1000;
    padding: 1rem 0;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-family: var(--font-heading);
    font-size: 2rem;
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.2rem;
}

.logo .tagline {
    font-size: 0.75rem;
    color: var(--dark-light);
    text-transform: uppercase;
    letter-spacing: 2px;
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
    align-items: center;
}

.nav-link {
    color: var(--dark);
    font-weight: 500;
    position: relative;
    padding: 0.5rem 0;
    transition: color var(--transition-fast);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-sunset);
    transition: width var(--transition-medium);
}

.nav-link:hover,
.nav-link.active {
    color: var(--primary-orange);
}

.nav-link:hover::after,
.nav-link.active::after {
    width: 100%;
}

/* Hamburger Menu */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 0.4rem;
}

.hamburger span {
    width: 30px;
    height: 3px;
    background: var(--dark);
    border-radius: 3px;
    transition: all var(--transition-medium);
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(8px, -8px);
}

/* ===================================
   HERO SECTION
   =================================== */

.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    padding-top: 80px;
}

.hero-content {
    text-align: center;
    max-width: 800px;
    z-index: 2;
    padding: var(--spacing-md);
}

.hero-title {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    margin-bottom: var(--spacing-md);
    color: var(--dark);
    line-height: 1.2;
}

.hero-subtitle {
    font-size: clamp(1rem, 2vw, 1.3rem);
    color: var(--dark-light);
    margin-bottom: var(--spacing-lg);
    line-height: 1.8;
}

.hero-buttons {
    display: flex;
    gap: var(--spacing-md);
    justify-content: center;
    flex-wrap: wrap;
}

/* Buttons */
.btn {
    padding: 1rem 2.5rem;
    border-radius: 50px;
    font-weight: 600;
    font-size: 1rem;
    cursor: pointer;
    transition: all var(--transition-medium);
    border: none;
    display: inline-block;
    text-align: center;
}

.btn-primary {
    background: var(--gradient-sunset);
    color: var(--white);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.3);
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(255, 107, 53, 0.4);
}

.btn-secondary {
    background: transparent;
    color: var(--dark);
    border: 2px solid var(--primary-orange);
}

.btn-secondary:hover {
    background: var(--primary-orange);
    color: var(--white);
    transform: translateY(-3px);
}

/* Floating Shapes */
.hero-visual {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
}

.floating-shape {
    position: absolute;
    border-radius: 50%;
    opacity: 0.6;
}

.shape-1 {
    width: 300px;
    height: 300px;
    background: var(--gradient-sunset);
    top: 10%;
    left: -10%;
}

.shape-2 {
    width: 200px;
    height: 200px;
    background: var(--gradient-ocean);
    bottom: 20%;
    right: -5%;
}

.shape-3 {
    width: 150px;
    height: 150px;
    background: var(--gradient-purple);
    top: 60%;
    left: 10%;
}

.shape-4 {
    width: 100px;
    height: 100px;
    background: var(--primary-coral);
    top: 30%;
    right: 15%;
}

/* Scroll Indicator */
.scroll-indicator {
    position: absolute;
    bottom: 40px;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    z-index: 2;
}

.scroll-indicator span {
    display: block;
    font-size: 0.9rem;
    color: var(--dark-light);
    margin-bottom: 0.5rem;
}

.scroll-arrow {
    width: 30px;
    height: 50px;
    border: 2px solid var(--primary-orange);
    border-radius: 20px;
    margin: 0 auto;
    position: relative;
}

.scroll-arrow::after {
    content: '';
    position: absolute;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    height: 6px;
    background: var(--primary-orange);
    border-radius: 50%;
    animation: scroll-down 2s infinite;
}

@keyframes scroll-down {
    0%, 100% { top: 10px; opacity: 1; }
    50% { top: 25px; opacity: 0.5; }
}

/* ===================================
   SECTION HEADERS
   =================================== */

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-lg);
}

.section-title {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 4vw, 3rem);
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.title-underline {
    width: 100px;
    height: 4px;
    background: var(--gradient-sunset);
    margin: 0 auto;
    border-radius: 2px;
}

.section-description {
    font-size: 1.1rem;
    color: var(--dark-light);
    margin-top: var(--spacing-md);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* ===================================
   ABOUT SECTION
   =================================== */

.about {
    padding: var(--spacing-xl) 0;
    background: var(--white);
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.about-text h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.about-text p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark-light);
    line-height: 1.8;
}

.about-text h4 {
    font-size: 1.5rem;
    margin-top: var(--spacing-lg);
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.about-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-md);
    margin: var(--spacing-lg) 0;
}

.stat-item {
    text-align: center;
    padding: var(--spacing-md);
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    border-radius: 15px;
}

.stat-number {
    display: block;
    font-size: 2.5rem;
    font-weight: 700;
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
}

.stat-label {
    display: block;
    font-size: 0.9rem;
    color: var(--dark-light);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.process-list {
    list-style: none;
    margin-top: var(--spacing-md);
}

.process-list li {
    padding: var(--spacing-sm) 0;
    padding-left: 2rem;
    position: relative;
    color: var(--dark-light);
    font-size: 1.05rem;
}

.process-list li::before {
    content: '→';
    position: absolute;
    left: 0;
    color: var(--primary-orange);
    font-size: 1.5rem;
    font-weight: 700;
}

.process-list li strong {
    color: var(--dark);
}

.about-image {
    position: relative;
}

.image-placeholder {
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.image-placeholder svg {
    width: 100%;
    height: auto;
}

/* ===================================
   CATALOG/GALLERY SECTION
   =================================== */

.catalog {
    padding: var(--spacing-xl) 0;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
}

.gallery-filters {
    display: flex;
    justify-content: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
    flex-wrap: wrap;
}

.filter-btn {
    padding: 0.75rem 2rem;
    border: 2px solid var(--primary-orange);
    background: transparent;
    color: var(--dark);
    border-radius: 50px;
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.filter-btn:hover,
.filter-btn.active {
    background: var(--gradient-sunset);
    color: var(--white);
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.3);
}

.gallery-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--spacing-md);
}

.gallery-item {
    background: var(--white);
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: all var(--transition-medium);
    cursor: pointer;
}

.gallery-item:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15);
}

.gallery-image {
    width: 100%;
    height: 300px;
    overflow: hidden;
    position: relative;
}

.gallery-image svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.gallery-item:hover .gallery-image svg {
    transform: scale(1.1);
}

.gallery-info {
    padding: var(--spacing-md);
}

.gallery-info h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
    color: var(--dark);
}

.gallery-info p {
    color: var(--dark-light);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-sm);
}

.view-details {
    color: var(--primary-orange);
    font-weight: 600;
    font-size: 0.9rem;
    display: inline-block;
    position: relative;
}

.view-details::after {
    content: ' →';
    transition: transform var(--transition-fast);
    display: inline-block;
}

.gallery-item:hover .view-details::after {
    transform: translateX(5px);
}

/* ===================================
   CONTACT SECTION
   =================================== */

.contact {
    padding: var(--spacing-xl) 0;
    background: var(--white);
}

.contact-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xl);
}

.contact-info h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.contact-info > p {
    color: var(--dark-light);
    margin-bottom: var(--spacing-lg);
    line-height: 1.8;
}

.info-items {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

.info-item {
    display: flex;
    gap: var(--spacing-md);
    align-items: flex-start;
}

.info-icon {
    font-size: 2rem;
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    border-radius: 15px;
    flex-shrink: 0;
}

.info-text h4 {
    font-size: 1.1rem;
    margin-bottom: 0.3rem;
    color: var(--dark);
}

.info-text p {
    color: var(--dark-light);
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.social-link {
    padding: 0.75rem 1.5rem;
    background: var(--gradient-sunset);
    color: var(--white);
    border-radius: 50px;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.social-link:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(255, 107, 53, 0.4);
}

/* Contact Form */
.contact-form-wrapper {
    position: relative;
}

.contact-form {
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
    padding: var(--spacing-lg);
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.form-group {
    margin-bottom: var(--spacing-md);
    position: relative;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 1rem;
    border: 2px solid var(--gray);
    border-radius: 10px;
    font-size: 1rem;
    font-family: var(--font-primary);
    transition: all var(--transition-medium);
    background: var(--white);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--primary-orange);
}

.form-group label {
    position: absolute;
    top: 1rem;
    left: 1rem;
    color: var(--dark-light);
    pointer-events: none;
    transition: all var(--transition-medium);
    background: var(--white);
    padding: 0 0.5rem;
}

.form-group input:focus + label,
.form-group textarea:focus + label,
.form-group select:focus + label,
.form-group input:not(:placeholder-shown) + label,
.form-group textarea:not(:placeholder-shown) + label,
.form-group select:valid + label {
    top: -0.5rem;
    left: 0.75rem;
    font-size: 0.85rem;
    color: var(--primary-orange);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
    opacity: 0;
}

.btn-submit {
    width: 100%;
    margin-top: var(--spacing-md);
}

.form-success {
    display: none;
    text-align: center;
    padding: var(--spacing-lg);
    background: var(--white);
    border-radius: 20px;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 100%;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.form-success.show {
    display: block;
}

.success-icon {
    width: 80px;
    height: 80px;
    background: var(--gradient-sunset);
    color: var(--white);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    margin: 0 auto var(--spacing-md);
}

.form-success h3 {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
    color: var(--dark);
}

.form-success p {
    color: var(--dark-light);
}

/* ===================================
   PRIVACY SECTION
   =================================== */

.privacy {
    padding: var(--spacing-xl) 0;
    background: linear-gradient(135deg, #FFF5F0 0%, #E8F8F5 100%);
}

.privacy-content {
    max-width: 900px;
    margin: 0 auto;
    background: var(--white);
    padding: var(--spacing-lg);
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.last-updated {
    color: var(--dark-light);
    font-style: italic;
    margin-bottom: var(--spacing-lg);
}

.privacy-section {
    margin-bottom: var(--spacing-lg);
}

.privacy-section h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark);
}

.privacy-section p {
    color: var(--dark-light);
    line-height: 1.8;
    margin-bottom: var(--spacing-sm);
}

.privacy-section ul {
    list-style: none;
    margin-top: var(--spacing-md);
}

.privacy-section ul li {
    padding: 0.5rem 0;
    padding-left: 2rem;
    position: relative;
    color: var(--dark-light);
}

.privacy-section ul li::before {
    content: '•';
    position: absolute;
    left: 0.75rem;
    color: var(--primary-orange);
    font-size: 1.5rem;
}

/* ===================================
   FOOTER
   =================================== */

.footer {
    background: var(--dark);
    color: var(--white);
    padding: var(--spacing-lg) 0 var(--spacing-md);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-brand h3 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
    background: var(--gradient-sunset);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.footer-brand p {
    color: var(--gray);
    line-height: 1.8;
}

.footer-links h4 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-md);
    color: var(--white);
}

.footer-links ul {
    list-style: none;
}

.footer-links ul li {
    margin-bottom: 0.75rem;
}

.footer-links ul li a {
    color: var(--gray);
    transition: color var(--transition-fast);
}

.footer-links ul li a:hover {
    color: var(--primary-orange);
}

.footer-newsletter h4 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-md);
    color: var(--white);
}

.footer-newsletter p {
    color: var(--gray);
    margin-bottom: var(--spacing-md);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border: none;
    border-radius: 50px;
    font-size: 0.95rem;
}

.newsletter-form button {
    padding: 0.75rem 1.5rem;
    background: var(--gradient-sunset);
    color: var(--white);
    border: none;
    border-radius: 50px;
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition-medium);
}

.newsletter-form button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(255, 107, 53, 0.4);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-bottom p {
    color: var(--gray);
}

/* ===================================
   RESPONSIVE DESIGN
   =================================== */

@media (max-width: 968px) {
    .nav-menu {
        position: fixed;
        left: -100%;
        top: 70px;
        flex-direction: column;
        background: var(--white);
        width: 100%;
        text-align: center;
        transition: left var(--transition-medium);
        box-shadow: 0 10px 27px rgba(0, 0, 0, 0.05);
        padding: var(--spacing-md) 0;
        gap: 0;
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-menu li {
        margin: 1rem 0;
    }

    .hamburger {
        display: flex;
    }

    .about-content,
    .contact-content {
        grid-template-columns: 1fr;
    }

    .about-stats {
        grid-template-columns: 1fr;
    }

    .hero-buttons {
        flex-direction: column;
        align-items: center;
    }

    .btn {
        width: 100%;
        max-width: 300px;
    }

    .gallery-grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    }
}

@media (max-width: 768px) {
    :root {
        --spacing-lg: 3rem;
        --spacing-xl: 4rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .gallery-filters {
        justify-content: flex-start;
        overflow-x: auto;
        padding-bottom: var(--spacing-sm);
    }

    .filter-btn {
        white-space: nowrap;
    }

    .footer-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .floating-shape {
        opacity: 0.3;
    }
}

@media (max-width: 480px) {
    .logo h1 {
        font-size: 1.5rem;
    }

    .gallery-grid {
        grid-template-columns: 1fr;
    }

    .contact-form {
        padding: var(--spacing-md);
    }
}

/* ===================================
   UTILITY CLASSES
   =================================== */

.hidden {
    display: none;
}

.fade-in {
    opacity: 0;
    animation: fadeIn 0.8s forwards;
}

@keyframes fadeIn {
    to {
        opacity: 1;
    }
}

/* Smooth scrolling for all browsers */
@media (prefers-reduced-motion: no-preference) {
    html {
        scroll-behavior: smooth;
    }
}
