// ===================================
// GSAP ANIMATIONS & INTERACTIONS
// ===================================

// Register ScrollTrigger plugin
gsap.registerPlugin(ScrollTrigger);

// ===================================
// MOBILE MENU TOGGLE
// ===================================

const hamburger = document.getElementById('hamburger');
const navMenu = document.getElementById('navMenu');
const navLinks = document.querySelectorAll('.nav-link');

hamburger.addEventListener('click', () => {
    hamburger.classList.toggle('active');
    navMenu.classList.toggle('active');
});

// Close menu when clicking on a link
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        hamburger.classList.remove('active');
        navMenu.classList.remove('active');
    });
});

// ===================================
// SMOOTH SCROLLING & ACTIVE NAV
// ===================================

// Update active nav link on scroll
const sections = document.querySelectorAll('section');

window.addEventListener('scroll', () => {
    let current = '';

    sections.forEach(section => {
        const sectionTop = section.offsetTop;
        const sectionHeight = section.clientHeight;

        if (pageYOffset >= sectionTop - 100) {
            current = section.getAttribute('id');
        }
    });

    navLinks.forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === `#${current}`) {
            link.classList.add('active');
        }
    });
});

// ===================================
// HERO ANIMATIONS
// ===================================

// Hero title animation
gsap.from('.hero-title', {
    duration: 1,
    y: 100,
    opacity: 0,
    ease: 'power4.out',
    delay: 0.3
});

// Hero subtitle animation
gsap.from('.hero-subtitle', {
    duration: 1,
    y: 50,
    opacity: 0,
    ease: 'power4.out',
    delay: 0.6
});

// Hero buttons animation
gsap.from('.hero-buttons', {
    duration: 1,
    y: 50,
    opacity: 0,
    ease: 'power4.out',
    delay: 0.9
});

// Floating shapes animation
gsap.to('.shape-1', {
    y: 30,
    x: 20,
    rotation: 10,
    duration: 4,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
});

gsap.to('.shape-2', {
    y: -40,
    x: -15,
    rotation: -15,
    duration: 5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
});

gsap.to('.shape-3', {
    y: 25,
    x: -30,
    rotation: 20,
    duration: 4.5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
});

gsap.to('.shape-4', {
    y: -20,
    x: 25,
    rotation: -10,
    duration: 3.5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
});

// Scroll indicator animation
gsap.from('.scroll-indicator', {
    duration: 1,
    opacity: 0,
    y: -20,
    ease: 'power2.out',
    delay: 1.2
});

// ===================================
// ABOUT SECTION ANIMATIONS
// ===================================

// Section title animations
gsap.from('.about .section-title', {
    scrollTrigger: {
        trigger: '.about',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    y: 50,
    opacity: 0,
    ease: 'power3.out'
});

gsap.from('.about .title-underline', {
    scrollTrigger: {
        trigger: '.about',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    width: 0,
    ease: 'power3.out',
    delay: 0.3
});

// About text animation
gsap.from('.about-text h3', {
    scrollTrigger: {
        trigger: '.about-text',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    x: -50,
    opacity: 0,
    ease: 'power3.out'
});

gsap.from('.about-text p', {
    scrollTrigger: {
        trigger: '.about-text',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    x: -50,
    opacity: 0,
    stagger: 0.2,
    ease: 'power3.out',
    delay: 0.2
});

// Stats animation
gsap.from('.stat-item', {
    scrollTrigger: {
        trigger: '.about-stats',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    y: 50,
    opacity: 0,
    stagger: 0.2,
    ease: 'power3.out'
});

// Process list animation
gsap.from('.process-list li', {
    scrollTrigger: {
        trigger: '.process-list',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.6,
    x: -30,
    opacity: 0,
    stagger: 0.15,
    ease: 'power2.out'
});

// About image animation
gsap.from('.about-image', {
    scrollTrigger: {
        trigger: '.about-image',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 1,
    x: 50,
    opacity: 0,
    ease: 'power3.out'
});

// ===================================
// GALLERY SECTION ANIMATIONS
// ===================================

// Gallery section title
gsap.from('.catalog .section-title', {
    scrollTrigger: {
        trigger: '.catalog',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    y: 50,
    opacity: 0,
    ease: 'power3.out'
});

gsap.from('.catalog .title-underline', {
    scrollTrigger: {
        trigger: '.catalog',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    width: 0,
    ease: 'power3.out',
    delay: 0.3
});

// Gallery filters animation
gsap.from('.filter-btn', {
    scrollTrigger: {
        trigger: '.gallery-filters',
        start: 'top 85%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.5,
    y: 30,
    opacity: 0,
    stagger: 0.1,
    ease: 'power2.out'
});

// Gallery items animation
gsap.from('.gallery-item', {
    scrollTrigger: {
        trigger: '.gallery-grid',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    duration: 0.8,
    y: 50,
    opacity: 0,
    stagger: 0.15,
    ease: 'power3.out'
});

// ===================================
// GALLERY FILTER FUNCTIONALITY
// ===================================

