/* ============================================
   CSS Variables & Reset
   ============================================ */
:root {
    /* Primary Colors - Vibrant African-inspired palette */
    --color-primary: #FF6B6B;
    --color-secondary: #4ECDC4;
    --color-accent: #FFD93D;
    --color-purple: #9B59B6;
    --color-orange: #FF9A56;
    --color-green: #2ECC71;
    --color-blue: #3498DB;

    /* Neutral Colors */
    --color-dark: #1a1a2e;
    --color-gray: #6c757d;
    --color-light: #f8f9fa;
    --color-white: #ffffff;

    /* Typography */
    --font-display: 'Playfair Display', serif;
    --font-body: 'Syne', sans-serif;

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;

    /* Border Radius */
    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.1);
    --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.15);
    --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.2);

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-base: 0.3s ease;
    --transition-slow: 0.5s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}

body {
    font-family: var(--font-body);
    background: var(--color-light);
    color: var(--color-dark);
    line-height: 1.6;
    overflow-x: hidden;
}

/* ============================================
   Navigation
   ============================================ */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    background: rgba(255, 255, 255, 0.98);
    backdrop-filter: blur(10px);
    box-shadow: var(--shadow-sm);
    transition: var(--transition-base);
}

.nav-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 1.25rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.75rem;
    font-weight: 800;
    font-family: var(--font-display);
    cursor: pointer;
}

.logo-afri {
    color: var(--color-primary);
}

.logo-art {
    color: var(--color-secondary);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2.5rem;
    align-items: center;
}

.nav-link {
    text-decoration: none;
    color: var(--color-dark);
    font-weight: 600;
    font-size: 0.95rem;
    position: relative;
    transition: var(--transition-base);
    padding: 0.5rem 0;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--color-primary), var(--color-secondary));
    transition: var(--transition-base);
}

.nav-link:hover,
.nav-link.active {
    color: var(--color-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
    width: 100%;
}

/* Hamburger Menu */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 5px;
}

.hamburger span {
    width: 28px;
    height: 3px;
    background: var(--color-dark);
    border-radius: var(--radius-full);
    transition: var(--transition-base);
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -7px);
}

/* ============================================
   Hero Section
   ============================================ */
.section {
    min-height: 100vh;
    padding: var(--spacing-xl) var(--spacing-md);
    position: relative;
}

.home-section {
    background: linear-gradient(135deg, #fff5f5 0%, #f0f9ff 50%, #fff5f0 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    padding-top: 120px;
}

.hero-container {
    max-width: 1400px;
    width: 100%;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.hero-content {
    z-index: 2;
}

.hero-badge {
    display: inline-block;
    padding: 0.5rem 1.25rem;
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    color: white;
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 600;
    margin-bottom: var(--spacing-md);
    box-shadow: var(--shadow-md);
}

.hero-title {
    font-family: var(--font-display);
    font-size: 4.5rem;
    font-weight: 900;
    line-height: 1.1;
    margin-bottom: var(--spacing-md);
}

.title-line {
    display: block;
}

.title-gradient {
    background: linear-gradient(135deg, var(--color-primary), var(--color-purple), var(--color-secondary));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-description {
    font-size: 1.25rem;
    color: var(--color-gray);
    margin-bottom: var(--spacing-lg);
    max-width: 550px;
    line-height: 1.8;
}

.hero-buttons {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.btn {
    padding: 1rem 2rem;
    border-radius: var(--radius-full);
    font-weight: 600;
    text-decoration: none;
    transition: var(--transition-base);
    cursor: pointer;
    border: none;
    font-size: 1rem;
    display: inline-block;
}

.btn-primary {
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    color: white;
    box-shadow: var(--shadow-md);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-secondary {
    background: transparent;
    color: var(--color-dark);
    border: 2px solid var(--color-dark);
}

.btn-secondary:hover {
    background: var(--color-dark);
    color: white;
}

/* Hero Visual */
.hero-visual {
    position: relative;
    height: 500px;
}

.floating-shape {
    position: absolute;
    border-radius: var(--radius-lg);
    animation: float 6s ease-in-out infinite;
}

.shape-1 {
    width: 180px;
    height: 180px;
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    top: 10%;
    right: 20%;
    animation-delay: 0s;
}

.shape-2 {
    width: 140px;
    height: 140px;
    background: linear-gradient(135deg, var(--color-secondary), var(--color-blue));
    bottom: 20%;
    right: 10%;
    animation-delay: 1s;
}

.shape-3 {
    width: 100px;
    height: 100px;
    background: linear-gradient(135deg, var(--color-purple), var(--color-primary));
    top: 40%;
    right: 50%;
    animation-delay: 2s;
}

.hero-circle {
    position: absolute;
    width: 400px;
    height: 400px;
    border-radius: 50%;
    background: linear-gradient(135deg, rgba(255, 107, 107, 0.1), rgba(78, 205, 196, 0.1));
    top: 50%;
    right: 20%;
    transform: translate(0, -50%);
    filter: blur(60px);
}

@keyframes float {
    0%, 100% {
        transform: translateY(0) rotate(0deg);
    }
    50% {
        transform: translateY(-20px) rotate(5deg);
    }
}

/* Scroll Indicator */
.scroll-indicator {
    position: absolute;
    bottom: var(--spacing-md);
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    color: var(--color-gray);
    font-size: 0.875rem;
}

.scroll-arrow {
    width: 24px;
    height: 40px;
    border: 2px solid var(--color-gray);
    border-radius: var(--radius-full);
    margin: 0.5rem auto;
    position: relative;
}

.scroll-arrow::before {
    content: '';
    position: absolute;
    top: 8px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    height: 6px;
    background: var(--color-gray);
    border-radius: 50%;
    animation: scroll 2s infinite;
}

@keyframes scroll {
    0% {
        top: 8px;
        opacity: 1;
    }
    100% {
        top: 24px;
        opacity: 0;
    }
}

/* ============================================
   Section Headers
   ============================================ */
.section-header {
    text-align: center;
    margin-bottom: var(--spacing-lg);
    max-width: 800px;
    margin-left: auto;
    margin-right: auto;
}

.section-badge {
    display: inline-block;
    padding: 0.5rem 1.25rem;
    background: rgba(78, 205, 196, 0.1);
    color: var(--color-secondary);
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.section-title {
    font-family: var(--font-display);
    font-size: 3.5rem;
    font-weight: 900;
    margin-bottom: var(--spacing-sm);
    color: var(--color-dark);
}

.section-description {
    font-size: 1.125rem;
    color: var(--color-gray);
    max-width: 600px;
    margin: 0 auto;
}

/* ============================================
   Catalog Section
   ============================================ */
.catalog-section {
    background: var(--color-white);
    padding-top: calc(var(--spacing-xl) + 80px);
}

.catalog-filters {
    display: flex;
    justify-content: center;
    gap: 1rem;
    margin-bottom: var(--spacing-lg);
    flex-wrap: wrap;
}

.filter-btn {
    padding: 0.75rem 1.5rem;
    border: 2px solid var(--color-light);
    background: var(--color-white);
    color: var(--color-dark);
    border-radius: var(--radius-full);
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-base);
}

.filter-btn:hover,
.filter-btn.active {
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    color: white;
    border-color: transparent;
    transform: translateY(-2px);
}

.catalog-grid {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 2rem;
    margin-bottom: var(--spacing-lg);
}

.artwork-card {
    background: var(--color-white);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition-base);
    cursor: pointer;
}

.artwork-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg);
}

.artwork-image {
    width: 100%;
    height: 300px;
    overflow: hidden;
    position: relative;
}

.artwork-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition-slow);
}

.artwork-card:hover .artwork-placeholder {
    transform: scale(1.05);
}

.placeholder-text {
    color: white;
    font-size: 1.5rem;
    font-weight: 700;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.3);
}

.artwork-info {
    padding: 1.5rem;
}

.artwork-title {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.artwork-description {
    color: var(--color-gray);
    margin-bottom: 1rem;
    font-size: 0.95rem;
}

.artwork-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.artwork-tag {
    padding: 0.375rem 0.875rem;
    background: rgba(78, 205, 196, 0.1);
    color: var(--color-secondary);
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 600;
}

.artwork-price {
    font-weight: 600;
    color: var(--color-primary);
}

.catalog-cta {
    text-align: center;
    padding: var(--spacing-lg) 0;
}

.catalog-cta p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
    color: var(--color-dark);
}

/* ============================================
   About Section
   ============================================ */
.about-section {
    background: linear-gradient(135deg, #fff5f5 0%, #f5f5ff 100%);
    padding-top: calc(var(--spacing-xl) + 80px);
}

.about-container {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.about-visual {
    position: relative;
}

.about-image-placeholder {
    width: 100%;
    height: 500px;
    background: linear-gradient(135deg, var(--color-purple), var(--color-primary));
    border-radius: var(--radius-lg);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.image-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.2);
}

.about-image-text {
    position: relative;
    z-index: 2;
    color: white;
    font-size: 2rem;
    font-weight: 700;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.3);
}

.about-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 2rem;
}

.stat-item {
    background: var(--color-white);
    padding: 1.5rem;
    border-radius: var(--radius-md);
    text-align: center;
    box-shadow: var(--shadow-sm);
}

.stat-number {
    display: block;
    font-size: 2rem;
    font-weight: 800;
    color: var(--color-primary);
    margin-bottom: 0.25rem;
    font-family: var(--font-display);
}

.stat-label {
    display: block;
    font-size: 0.875rem;
    color: var(--color-gray);
}

.about-content {
    padding: var(--spacing-md);
}

.about-text p {
    margin-bottom: 1.5rem;
    font-size: 1.0625rem;
    line-height: 1.8;
    color: var(--color-dark);
}

.about-values {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: var(--spacing-lg);
}

.value-item {
    text-align: center;
}

.value-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.value-item h4 {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.value-item p {
    color: var(--color-gray);
    font-size: 0.95rem;
}

/* ============================================
   Contact Section
   ============================================ */
.contact-section {
    background: var(--color-white);
    padding-top: calc(var(--spacing-xl) + 80px);
}

.contact-container {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
}

.contact-info {
    padding: var(--spacing-md);
}

.contact-details {
    margin: var(--spacing-lg) 0;
}

.contact-item {
    display: flex;
    gap: 1.5rem;
    margin-bottom: 2rem;
    align-items: flex-start;
}

.contact-icon {
    font-size: 2rem;
    flex-shrink: 0;
}

.contact-text h4 {
    font-size: 1.125rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
    color: var(--color-dark);
}

.contact-text a,
.contact-text p {
    color: var(--color-gray);
    text-decoration: none;
    transition: var(--transition-base);
}

.contact-text a:hover {
    color: var(--color-primary);
}

.social-links {
    margin-top: var(--spacing-lg);
}

.social-links h4 {
    font-size: 1.125rem;
    margin-bottom: 1rem;
    color: var(--color-dark);
}

.social-icons {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.social-icon {
    padding: 0.75rem 1.5rem;
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    color: white;
    text-decoration: none;
    border-radius: var(--radius-full);
    font-weight: 600;
    transition: var(--transition-base);
}

.social-icon:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

/* Contact Form */
.contact-form-wrapper {
    background: var(--color-light);
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    position: relative;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-group label {
    font-weight: 600;
    color: var(--color-dark);
    font-size: 0.95rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    padding: 0.875rem 1.25rem;
    border: 2px solid rgba(0, 0, 0, 0.1);
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 1rem;
    transition: var(--transition-base);
    background: var(--color-white);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 120px;
}

.btn-submit {
    width: 100%;
    margin-top: 1rem;
}

.form-success {
    position: absolute;
    inset: 0;
    background: var(--color-white);
    border-radius: var(--radius-lg);
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: var(--spacing-md);
}

.form-success.show {
    display: flex;
}

.success-icon {
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--color-green), var(--color-secondary));
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    margin-bottom: 1.5rem;
}

.form-success h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.form-success p {
    color: var(--color-gray);
    font-size: 1.125rem;
}

/* ============================================
   Privacy Section
   ============================================ */
.privacy-section {
    background: var(--color-light);
    padding-top: calc(var(--spacing-xl) + 80px);
    min-height: auto;
}

.privacy-container {
    max-width: 900px;
    margin: 0 auto;
}

.privacy-updated {
    color: var(--color-gray);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-lg);
    text-align: center;
}

.privacy-content {
    background: var(--color-white);
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-sm);
}

.privacy-block {
    margin-bottom: var(--spacing-lg);
}

.privacy-block:last-child {
    margin-bottom: 0;
}

.privacy-block h3 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--color-dark);
}

.privacy-block p,
.privacy-block li {
    color: var(--color-gray);
    line-height: 1.8;
    margin-bottom: 1rem;
}

.privacy-block ul {
    padding-left: 1.5rem;
    margin-top: 1rem;
}

.privacy-block li {
    margin-bottom: 0.5rem;
}

.privacy-block a {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 600;
}

.privacy-block a:hover {
    text-decoration: underline;
}

/* ============================================
   Footer
   ============================================ */
.footer {
    background: var(--color-dark);
    color: var(--color-white);
    padding: var(--spacing-lg) var(--spacing-md) var(--spacing-md);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-md);
}

.footer-brand .logo {
    margin-bottom: 1rem;
}

.footer-brand p {
    color: rgba(255, 255, 255, 0.7);
    max-width: 400px;
}

.footer-column h4 {
    margin-bottom: 1rem;
    font-size: 1.125rem;
}

.footer-column ul {
    list-style: none;
}

.footer-column li {
    margin-bottom: 0.75rem;
}

.footer-column a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: var(--transition-base);
}

.footer-column a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.875rem;
}

/* ============================================
   Responsive Design
   ============================================ */
@media (max-width: 1024px) {
    .hero-container,
    .about-container,
    .contact-container {
        grid-template-columns: 1fr;
        gap: var(--spacing-md);
    }

    .hero-visual {
        height: 400px;
    }

    .hero-title {
        font-size: 3.5rem;
    }

    .section-title {
        font-size: 2.75rem;
    }

    .catalog-grid {
        grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    }

    .about-stats,
    .about-values {
        grid-template-columns: repeat(3, 1fr);
    }

    .footer-content {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-menu {
        position: fixed;
        left: -100%;
        top: 80px;
        flex-direction: column;
        background: var(--color-white);
        width: 100%;
        text-align: center;
        transition: var(--transition-base);
        box-shadow: var(--shadow-lg);
        padding: 2rem;
        gap: 1.5rem;
