    .hero-title {
        font-size: 2.75rem;
    }

    .section-title {
        font-size: 2.25rem;
    }

    .hero-buttons {
        flex-direction: column;
    }

    .btn {
        width: 100%;
        text-align: center;
    }

    .catalog-grid {
        grid-template-columns: 1fr;
    }

    .about-stats,
    .about-values {
        grid-template-columns: 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .footer-brand p {
        margin: 0 auto;
    }

    .catalog-filters {
        flex-direction: column;
    }

    .filter-btn {
        width: 100%;
    }

    .contact-container {
        padding: var(--spacing-sm);
    }
}

@media (max-width: 480px) {
    .hero-title {
        font-size: 2.25rem;
    }

    .section-title {
        font-size: 1.875rem;
    }

    .nav-container {
        padding: 1rem 1.5rem;
    }

    .logo {
        font-size: 1.5rem;
    }
}

/* ============================================
   Utility Classes
   ============================================ */
.hide {
    display: none !important;
}

.show {
    display: block !important;
}

/* Smooth transitions for filter animations */
.artwork-card {
    transition: opacity 0.3s ease, transform 0.3s ease;
}

.artwork-card.hidden {
    opacity: 0;
    transform: scale(0.95);
    pointer-events: none;
}

