    font-weight: 900;
    line-height: 1.1;
    margin-bottom: var(--spacing-md);
}

.title-line {
    display: block;
}

.title-gradient {
    background: linear-gradient(135deg, var(--color-primary), var(--color-purple), var(--color-secondary));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-description {
    font-size: 1.25rem;
