}

/* Hero Visual */
.hero-visual {
    position: relative;
    height: 500px;
}

.floating-shape {
    position: absolute;
    border-radius: var(--radius-lg);
    animation: float 6s ease-in-out infinite;
}

.shape-1 {
    width: 180px;
    height: 180px;
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    top: 10%;
    right: 20%;
