    color: white;
    border-color: transparent;
    transform: translateY(-2px);
}

.catalog-grid {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 2rem;
    margin-bottom: var(--spacing-lg);
}

.artwork-card {
    background: var(--color-white);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition-base);
    cursor: pointer;
}

.artwork-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg);
}

.artwork-image {
    width: 100%;
    height: 300px;
    overflow: hidden;
    position: relative;
}

.artwork-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition-slow);
}

.artwork-card:hover .artwork-placeholder {
    transform: scale(1.05);
}

.placeholder-text {
    color: white;
    font-size: 1.5rem;
    font-weight: 700;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.3);
}

.artwork-info {
    padding: 1.5rem;
}

.artwork-title {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.artwork-description {
    color: var(--color-gray);
    margin-bottom: 1rem;
    font-size: 0.95rem;
}

.artwork-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.artwork-tag {
    padding: 0.375rem 0.875rem;
    background: rgba(78, 205, 196, 0.1);
    color: var(--color-secondary);
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 600;
}

.artwork-price {
    font-weight: 600;
    color: var(--color-primary);
}

.catalog-cta {
    text-align: center;
    padding: var(--spacing-lg) 0;
}

.catalog-cta p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
    color: var(--color-dark);
}

/* ============================================
   About Section
   ============================================ */
.about-section {
    background: linear-gradient(135deg, #fff5f5 0%, #f5f5ff 100%);
    padding-top: calc(var(--spacing-xl) + 80px);
}

.about-container {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.about-visual {
    position: relative;
}

.about-image-placeholder {
    width: 100%;
    height: 500px;
    background: linear-gradient(135deg, var(--color-purple), var(--color-primary));
    border-radius: var(--radius-lg);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.image-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.2);
