    font-size: 1.0625rem;
    line-height: 1.8;
    color: var(--color-dark);
}

.about-values {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: var(--spacing-lg);
}

.value-item {
    text-align: center;
}

.value-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.value-item h4 {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.value-item p {
    color: var(--color-gray);
    font-size: 0.95rem;
}

/* ============================================
   Contact Section
   ============================================ */
.contact-section {
    background: var(--color-white);
    padding-top: calc(var(--spacing-xl) + 80px);
}

.contact-container {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
}

.contact-info {
    padding: var(--spacing-md);
}

.contact-details {
    margin: var(--spacing-lg) 0;
}

.contact-item {
    display: flex;
    gap: 1.5rem;
    margin-bottom: 2rem;
    align-items: flex-start;
}

.contact-icon {
    font-size: 2rem;
    flex-shrink: 0;
}

.contact-text h4 {
    font-size: 1.125rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
    color: var(--color-dark);
}

.contact-text a,
.contact-text p {
    color: var(--color-gray);
    text-decoration: none;
    transition: var(--transition-base);
}

.contact-text a:hover {
    color: var(--color-primary);
}

.social-links {
    margin-top: var(--spacing-lg);
}

.social-links h4 {
    font-size: 1.125rem;
    margin-bottom: 1rem;
    color: var(--color-dark);
}

.social-icons {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.social-icon {
    padding: 0.75rem 1.5rem;
    background: linear-gradient(135deg, var(--color-primary), var(--color-orange));
    color: white;
    text-decoration: none;
    border-radius: var(--radius-full);
    font-weight: 600;
    transition: var(--transition-base);
}

.social-icon:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

/* Contact Form */
.contact-form-wrapper {
    background: var(--color-light);
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    position: relative;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-group label {
    font-weight: 600;
    color: var(--color-dark);
    font-size: 0.95rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    padding: 0.875rem 1.25rem;
    border: 2px solid rgba(0, 0, 0, 0.1);
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 1rem;
    transition: var(--transition-base);
    background: var(--color-white);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 120px;
}

.btn-submit {
    width: 100%;
    margin-top: 1rem;
}

.form-success {
    position: absolute;
    inset: 0;
    background: var(--color-white);
    border-radius: var(--radius-lg);
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: var(--spacing-md);
}

.form-success.show {
    display: flex;
}

.success-icon {
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--color-green), var(--color-secondary));
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    margin-bottom: 1.5rem;
}

.form-success h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
    color: var(--color-dark);
}

.form-success p {
    color: var(--color-gray);
    font-size: 1.125rem;
}

/* ============================================
   Privacy Section
   ============================================ */
.privacy-section {
    background: var(--color-light);
    padding-top: calc(var(--spacing-xl) + 80px);
    min-height: auto;
}

.privacy-container {
    max-width: 900px;
    margin: 0 auto;
}

.privacy-updated {
    color: var(--color-gray);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-lg);
    text-align: center;
}

.privacy-content {
    background: var(--color-white);
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-sm);
}

.privacy-block {
    margin-bottom: var(--spacing-lg);
}

.privacy-block:last-child {
    margin-bottom: 0;
}

.privacy-block h3 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--color-dark);
}

.privacy-block p,
.privacy-block li {
    color: var(--color-gray);
    line-height: 1.8;
    margin-bottom: 1rem;
}

.privacy-block ul {
    padding-left: 1.5rem;
    margin-top: 1rem;
}

.privacy-block li {
    margin-bottom: 0.5rem;
}

.privacy-block a {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 600;
}

.privacy-block a:hover {
    text-decoration: underline;
}

/* ============================================
   Footer
   ============================================ */
.footer {
    background: var(--color-dark);
    color: var(--color-white);
    padding: var(--spacing-lg) var(--spacing-md) var(--spacing-md);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-md);
}

.footer-brand .logo {
    margin-bottom: 1rem;
}

.footer-brand p {
    color: rgba(255, 255, 255, 0.7);
    max-width: 400px;
}

.footer-column h4 {
    margin-bottom: 1rem;
    font-size: 1.125rem;
}

.footer-column ul {
    list-style: none;
}

.footer-column li {
    margin-bottom: 0.75rem;
}

.footer-column a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: var(--transition-base);
}

.footer-column a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.875rem;
}

/* ============================================
   Responsive Design
   ============================================ */
@media (max-width: 1024px) {
    .hero-container,
    .about-container,
    .contact-container {
        grid-template-columns: 1fr;
        gap: var(--spacing-md);
    }

    .hero-visual {
        height: 400px;
    }

    .hero-title {
        font-size: 3.5rem;
    }

    .section-title {
        font-size: 2.75rem;
    }

    .catalog-grid {
        grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    }

    .about-stats,
    .about-values {
        grid-template-columns: repeat(3, 1fr);
    }

    .footer-content {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-menu {
        position: fixed;
        left: -100%;
        top: 80px;
        flex-direction: column;
        background: var(--color-white);
        width: 100%;
        text-align: center;
        transition: var(--transition-base);
        box-shadow: var(--shadow-lg);
        padding: 2rem;
        gap: 1.5rem;
    }

    .nav-menu.active {
        left: 0;
    }

    .hamburger {
        display: flex;
    }

    .section {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .hero-title {
        font-size: 2.75rem;
    }

    .section-title {
        font-size: 2.25rem;
    }

    .hero-buttons {
        flex-direction: column;
    }

    .btn {
        width: 100%;
        text-align: center;
    }

    .catalog-grid {
        grid-template-columns: 1fr;
    }

    .about-stats,
    .about-values {
        grid-template-columns: 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .footer-brand p {
        margin: 0 auto;
    }

    .catalog-filters {
        flex-direction: column;
    }

    .filter-btn {
        width: 100%;
    }

    .contact-container {
        padding: var(--spacing-sm);
    }
}

@media (max-width: 480px) {
    .hero-title {
        font-size: 2.25rem;
    }

    .section-title {
        font-size: 1.875rem;
    }

    .nav-container {
        padding: 1rem 1.5rem;
    }

    .logo {
        font-size: 1.5rem;
    }
}

/* ============================================
   Utility Classes
   ============================================ */
.hide {
    display: none !important;
}

.show {
    display: block !important;
}

/* Smooth transitions for filter animations */
.artwork-card {
    transition: opacity 0.3s ease, transform 0.3s ease;
}

.artwork-card.hidden {
    opacity: 0;
    transform: scale(0.95);
    pointer-events: none;
}
