    stagger: 0.15,
    ease: 'power3.out'
});

// ============================================
// Contact Section Animations
// ============================================
gsap.from('.contact-item', {
    scrollTrigger: {
        trigger: '.contact-details',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    x: -40,
    opacity: 0,
    duration: 0.8,
    stagger: 0.15,
    ease: 'power3.out'
});

gsap.from('.contact-form-wrapper', {
    scrollTrigger: {
        trigger: '.contact-form-wrapper',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    x: 40,
    opacity: 0,
    duration: 1,
    ease: 'power3.out'
});

gsap.from('.social-icon', {
    scrollTrigger: {
        trigger: '.social-links',
        start: 'top 85%',
        toggleActions: 'play none none reverse'
    },
    scale: 0,
    opacity: 0,
    duration: 0.6,
    stagger: 0.1,
    ease: 'back.out(1.7)'
});

// ============================================
// Contact Form Handling
// ============================================
const contactForm = document.getElementById('contactForm');
const formSuccess = document.getElementById('formSuccess');

contactForm.addEventListener('submit', (e) => {
    e.preventDefault();

    // Simulate form submission
    const formData = new FormData(contactForm);

    // Animate form out
    gsap.to('.contact-form', {
        opacity: 0,
        y: -20,
        duration: 0.4,
        ease: 'power2.in',
        onComplete: () => {
            contactForm.style.display = 'none';
            formSuccess.classList.add('show');

            // Animate success message in
            gsap.from('.success-icon', {
                scale: 0,
                duration: 0.6,
                ease: 'back.out(1.7)'
            });

            gsap.from('.form-success h3, .form-success p', {
                y: 20,
                opacity: 0,
                duration: 0.6,
                stagger: 0.2,
                delay: 0.3
            });

            // Reset form after 5 seconds
            setTimeout(() => {
                gsap.to('.form-success', {
                    opacity: 0,
                    duration: 0.4,
                    onComplete: () => {
                        formSuccess.classList.remove('show');
                        contactForm.reset();
                        contactForm.style.display = 'flex';
                        gsap.to('.contact-form', {
                            opacity: 1,
                            y: 0,
                            duration: 0.4
                        });
                    }
                });
            }, 5000);
        }
    });
});

// ============================================
// Privacy Section Animations
// ============================================
gsap.from('.privacy-block', {
    scrollTrigger: {
        trigger: '.privacy-content',
        start: 'top 80%',
        toggleActions: 'play none none reverse'
    },
    y: 40,
    opacity: 0,
    duration: 0.6,
    stagger: 0.1,
    ease: 'power3.out'
});

// ============================================
// Footer Animations
// ============================================
gsap.from('.footer-brand, .footer-column', {
    scrollTrigger: {
        trigger: '.footer',
        start: 'top 90%',
        toggleActions: 'play none none reverse'
    },
    y: 30,
    opacity: 0,
    duration: 0.8,
    stagger: 0.15,
    ease: 'power3.out'
});

// ============================================
// Parallax Effect for Floating Shapes
// ============================================
function initParallax() {
    const shapes = document.querySelectorAll('.floating-shape');

    window.addEventListener('mousemove', (e) => {
        const mouseX = e.clientX / window.innerWidth;
        const mouseY = e.clientY / window.innerHeight;

        shapes.forEach((shape, index) => {
            const speed = (index + 1) * 20;
            const x = (mouseX - 0.5) * speed;
            const y = (mouseY - 0.5) * speed;

            gsap.to(shape, {
                x: x,
                y: y,
                duration: 1,
                ease: 'power2.out'
            });
        });
    });
}

initParallax();

// ============================================
// Artwork Card Hover Effects
// ============================================
artworkCards.forEach(card => {
    card.addEventListener('mouseenter', () => {
        gsap.to(card.querySelector('.artwork-placeholder'), {
            scale: 1.05,
            duration: 0.4,
            ease: 'power2.out'
        });
    });

    card.addEventListener('mouseleave', () => {
        gsap.to(card.querySelector('.artwork-placeholder'), {
            scale: 1,
            duration: 0.4,
            ease: 'power2.out'
        });
    });
});

// ============================================
// Scroll Progress Indicator (Optional Enhancement)
// ============================================
function createScrollProgress() {
    const progressBar = document.createElement('div');
    progressBar.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        width: 0%;
        height: 4px;
        background: linear-gradient(90deg, #FF6B6B, #4ECDC4);
        z-index: 9999;
        transition: width 0.1s ease;
    `;
    document.body.appendChild(progressBar);

    window.addEventListener('scroll', () => {
        const windowHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        const scrolled = (window.scrollY / windowHeight) * 100;
        progressBar.style.width = scrolled + '%';
    });
}

createScrollProgress();

// ============================================
// Navbar Background on Scroll
// ============================================
const navbar = document.querySelector('.navbar');

window.addEventListener('scroll', () => {
    if (window.scrollY > 100) {
        navbar.style.boxShadow = '0 4px 16px rgba(0, 0, 0, 0.1)';
    } else {
        navbar.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.1)';
    }
});

// ============================================
// Smooth Number Counter Animation for Stats
// ============================================
function animateCounter(element, target, duration = 2000) {
    const start = 0;
    const increment = target / (duration / 16);
    let current = start;

    const timer = setInterval(() => {
        current += increment;
        if (current >= target) {
            element.textContent = target;
            clearInterval(timer);
        } else {
            element.textContent = Math.floor(current);
        }
    }, 16);
}

// Trigger counter animation when stats are in view
ScrollTrigger.create({
    trigger: '.about-stats',
    start: 'top 80%',
    onEnter: () => {
        const statNumbers = document.querySelectorAll('.stat-number');
        animateCounter(statNumbers[0], 500);
        animateCounter(statNumbers[1], 2000);
        animateCounter(statNumbers[2], 15);
    },
    once: true
});

// ============================================
// Lazy Loading for Images (Future Enhancement)
// ============================================
// When actual images are added, implement intersection observer
// for lazy loading to improve performance

// ============================================
// Accessibility Enhancements
// ============================================
// Add keyboard navigation support
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && navMenu.classList.contains('active')) {
        hamburger.classList.remove('active');
        navMenu.classList.remove('active');
    }
});

// Focus trap for mobile menu
const focusableElements = navMenu.querySelectorAll('a, button');
const firstFocusable = focusableElements[0];
const lastFocusable = focusableElements[focusableElements.length - 1];

navMenu.addEventListener('keydown', (e) => {
    if (e.key === 'Tab') {
        if (e.shiftKey) {
            if (document.activeElement === firstFocusable) {
                e.preventDefault();
                lastFocusable.focus();
            }
        } else {
            if (document.activeElement === lastFocusable) {
                e.preventDefault();
                firstFocusable.focus();
            }
        }
    }
});

// ============================================
// Performance Optimization
// ============================================
// Debounce scroll events
function debounce(func, wait = 10) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// Apply debounce to scroll-heavy functions
window.addEventListener('scroll', debounce(updateActiveNav, 10));

// ============================================
// Console Welcome Message
// ============================================
console.log('%cWelcome to AfriArt! 🎨', 'color: #FF6B6B; font-size: 24px; font-weight: bold;');
console.log('%cTransforming waste into wonder, one piece at a time.', 'color: #4ECDC4; font-size: 14px;');
console.log('%cInterested in the code? Visit our GitHub!', 'color: #6c757d; font-size: 12px;');
