.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px 0;
}

.logo {
    display: flex;
    align-items: center;
    gap: 12px;
}

.site-logo {
    height: 60px;
    width: auto;
    object-fit: contain;
}

.logo-text-container {
    display: flex;
    flex-direction: column;
}

.logo-text {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
}

.logo .budget {
    font-family: 'Poppins', sans-serif;
    font-weight: 700;
    font-size: 24px;
    color: var(--primary-color);
    margin-right: 5px;
}

.logo .cleaning {
    font-family: 'Poppins', sans-serif;
    font-weight: 600;
    font-size: 18px;
    color: var(--secondary-color);
}

.tagline {
    font-size: 12px;
    color: var(--light-text);
    font-style: italic;
    margin-top: 2px;
}

.nav-menu {
    display: flex;
    list-style: none;
    align-items: center;
}

.nav-link {
    margin: 0 15px;
    font-weight: 500;
    color: var(--dark-text);
    transition: var(--transition);
    position: relative;
}

.nav-link:hover {
    color: var(--primary-color);
}

.nav-link.active {
    color: var(--primary-color);
}

.nav-link.active::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 100%;
    height: 2px;
    background-color: var(--primary-color);
}

.nav-cta {
    margin-left: 15px;
}

.nav-toggle {
    display: none;
    flex-direction: column;
    cursor: pointer;
}

.nav-toggle span {
    width: 25px;
    height: 3px;
    background-color: var(--primary-color);
    margin: 3px 0;
    transition: var(--transition);
}

/* Hero Section */
.hero {
    background: linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url('images/hero-bg.jpg') no-repeat center center/cover;
    color: var(--white);
    padding: 180px 0 100px;
    position: relative;
    margin-top: 70px;
    min-height: 500px;
}

.hero-content {
    max-width: 800px;
    text-align: center;
    margin: 0 auto;
    position: relative;
    z-index: 2;
}

.hero-title {
    font-size: 2.8rem;
    margin-bottom: 20px;
}

.hero-subtitle {
    font-size: 1.2rem;
    margin-bottom: 30px;
    opacity: 0.9;
    max-width: 700px;
    margin-left: auto;
    margin-right: auto;
}

.hero-tagline {
    font-size: 1.4rem;
    font-weight: 600;
    margin-bottom: 30px;
    color: var(--accent-color);
}

.hero-btns {
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: wrap;
}

.hero-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 100px;
    background: linear-gradient(to top, var(--light-bg), transparent);
}

/* Services Section */
.section-header {
    text-align: center;
    margin-bottom: 50px;
}

.section-header h2 {
    font-size: 2.2rem;
    color: var(--primary-color);
    margin-bottom: 10px;
}

.section-header p {
    color: var(--light-text);
    font-size: 1.1rem;
}

.services {
    padding: 80px 0;
    background-color: var(--light-bg);
}

