@media (max-width: 992px) {
    .property-grid,
    .garden-grid,
    .contact-grid {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .hero-title {
        font-size: 2.2rem;
    }

    .services-grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    }
}

@media (max-width: 768px) {
    .nav-toggle {
        display: flex;
    }

    .nav-menu {
        position: fixed;
        top: 70px;
        right: -100%;
        flex-direction: column;
        background-color: var(--white);
        width: 100%;
        text-align: center;
        transition: 0.3s;
        box-shadow: 0 10px 27px rgba(0, 0, 0, 0.05);
        padding: 20px 0;
        z-index: 999;
    }

    .nav-menu.active {
        right: 0;
    }

    .nav-link {
        margin: 15px 0;
        display: block;
    }

    .nav-cta {
        margin: 15px 0 0;
    }

    .hero {
        padding: 150px 0 80px;
    }

    .hero-title {
        font-size: 1.8rem;
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .hero-btns {
        flex-direction: column;
        align-items: center;
    }

    .hero-btns .btn {
        width: 100%;
        max-width: 300px;
        margin-bottom: 10px;
    }

    .section-header h2 {
        font-size: 1.8rem;
    }

    .value-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 576px) {
    .container {
        padding: 0 15px;
    }

    .logo .budget {
        font-size: 20px;
    }

    .logo .cleaning {
        font-size: 16px;
    }

    .service-card,
    .value-card {
        padding: 20px;
    }

    .image-placeholder {
        height: 200px;
        font-size: 3rem;
    }

    .contact-form {
        padding: 20px;
    }
}

