    box-shadow: var(--shadow);
    transition: var(--transition);
    text-align: center;
}

.service-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
}

.service-icon {
    font-size: 2.5rem;
    color: var(--primary-color);
    margin-bottom: 20px;
}

.service-card h3 {
    font-size: 1.3rem;
    margin-bottom: 15px;
    color: var(--dark-text);
}

.service-card p {
    color: var(--light-text);
    font-size: 0.95rem;
}

/* Property Management Section */
.property-section {
    padding: 80px 0;
    background-color: var(--white);
}

.property-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    align-items: center;
}

.property-content h2 {
    font-size: 2rem;
    color: var(--primary-color);
    margin-bottom: 20px;
}

.property-content p {
    margin-bottom: 25px;
    font-size: 1.05rem;
}

.feature-list {
    list-style: none;
}

.feature-list li {
    margin-bottom: 10px;
    display: flex;
    align-items: center;
}

.feature-list i {
    color: var(--secondary-color);
    margin-right: 10px;
    font-size: 1.1rem;
}

.image-placeholder {
    background-color: var(--light-bg);
    height: 300px;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    color: var(--primary-color);
    font-size: 5rem;
}

.image-placeholder p {
    margin-top: 15px;
    font-size: 1.2rem;
    font-weight: 500;
}

/* Value Added Services */
.value-services {
    padding: 80px 0;
    background-color: var(--light-bg);
}

.value-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 30px;
}

.value-card {
    background-color: var(--white);
    padding: 30px;
    border-radius: 8px;
    text-align: center;
    box-shadow: var(--shadow);
    transition: var(--transition);
}

.value-card:hover {
    transform: translateY(-5px);
}

.value-card i {
    font-size: 2.5rem;
    color: var(--accent-color);
    margin-bottom: 20px;
}

.value-card h3 {
    font-size: 1.3rem;
    margin-bottom: 15px;
    color: var(--dark-text);
}

/* Garden Services Section */
.garden-section {
    padding: 80px 0;
    background-color: var(--white);
}

.garden-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    align-items: center;
}

.garden-content h2 {
    font-size: 2rem;
    color: var(--primary-color);
    margin-bottom: 20px;
}

/* About Section */
.about {
    padding: 80px 0;
    background-color: var(--white);
}

.about-content {
    max-width: 900px;
    margin: 0 auto;
}

.about-text h3 {
    font-size: 1.8rem;
    color: var(--primary-color);
    margin-bottom: 15px;
    margin-top: 30px;
}

.about-text h3:first-child {
    margin-top: 0;
}

.about-text p {
    margin-bottom: 20px;
